export const WINDOWS_HUD_SOURCES: Record<string, string> = {"HudLogic.cs":"// Remote Hands Windows HUD: the parts that do not draw anything (protocol, JSON, state), kept free of\n// System.Windows.Forms so they can be compiled and tested on any computer. C# 5 only: this is built on the\n// user's PC by the compiler that ships with Windows (csc.exe, C# 5), so no ?., $\"\", nameof or expression bodies.\nusing System;\nusing System.Collections.Generic;\nusing System.Globalization;\nusing System.Text;\n\nnamespace RemoteHands\n{\n    /// <summary>A small JSON reader and writer: enough for the lines this program exchanges with the daemon.</summary>\n    public static class Json\n    {\n        /// <summary>Parses one JSON value. Objects are Dictionary&lt;string, object&gt;, arrays List&lt;object&gt;, numbers double.</summary>\n        /// <returns>null when the text is not valid JSON (the caller ignores that line).</returns>\n        public static object Parse(string text)\n        {\n            if (text == null) return null;\n            try\n            {\n                int i = 0;\n                SkipSpace(text, ref i);\n                object value = ReadValue(text, ref i, 0);\n                SkipSpace(text, ref i);\n                if (i != text.Length) return null;\n                return value;\n            }\n            catch (FormatException)\n            {\n                return null;\n            }\n        }\n\n        static void SkipSpace(string s, ref int i)\n        {\n            while (i < s.Length && (s[i] == ' ' || s[i] == '\\t' || s[i] == '\\r' || s[i] == '\\n')) i++;\n        }\n\n        static object ReadValue(string s, ref int i, int depth)\n        {\n            if (depth > 64) throw new FormatException(\"too deep\");\n            if (i >= s.Length) throw new FormatException(\"unexpected end\");\n            char c = s[i];\n            if (c == '{') return ReadObject(s, ref i, depth);\n            if (c == '[') return ReadArray(s, ref i, depth);\n            if (c == '\"') return ReadString(s, ref i);\n            if (c == 't') { Expect(s, ref i, \"true\"); return true; }\n            if (c == 'f') { Expect(s, ref i, \"false\"); return false; }\n            if (c == 'n') { Expect(s, ref i, \"null\"); return null; }\n            return ReadNumber(s, ref i);\n        }\n\n        static void Expect(string s, ref int i, string word)\n        {\n            if (string.CompareOrdinal(s, i, word, 0, word.Length) != 0) throw new FormatException(\"bad literal\");\n            i += word.Length;\n        }\n\n        static object ReadNumber(string s, ref int i)\n        {\n            int start = i;\n            while (i < s.Length && \"+-0123456789.eE\".IndexOf(s[i]) >= 0) i++;\n            double d;\n            if (i == start || !double.TryParse(s.Substring(start, i - start), NumberStyles.Float, CultureInfo.InvariantCulture, out d))\n                throw new FormatException(\"bad number\");\n            return d;\n        }\n\n        static Dictionary<string, object> ReadObject(string s, ref int i, int depth)\n        {\n            var result = new Dictionary<string, object>();\n            i++; // {\n            SkipSpace(s, ref i);\n            if (i < s.Length && s[i] == '}') { i++; return result; }\n            while (true)\n            {\n                SkipSpace(s, ref i);\n                if (i >= s.Length || s[i] != '\"') throw new FormatException(\"expected key\");\n                string key = ReadString(s, ref i);\n                SkipSpace(s, ref i);\n                if (i >= s.Length || s[i] != ':') throw new FormatException(\"expected colon\");\n                i++;\n                SkipSpace(s, ref i);\n                result[key] = ReadValue(s, ref i, depth + 1);\n                SkipSpace(s, ref i);\n                if (i >= s.Length) throw new FormatException(\"unexpected end\");\n                if (s[i] == ',') { i++; continue; }\n                if (s[i] == '}') { i++; return result; }\n                throw new FormatException(\"expected , or }\");\n            }\n        }\n\n        static List<object> ReadArray(string s, ref int i, int depth)\n        {\n            var result = new List<object>();\n            i++; // [\n            SkipSpace(s, ref i);\n            if (i < s.Length && s[i] == ']') { i++; return result; }\n            while (true)\n            {\n                SkipSpace(s, ref i);\n                result.Add(ReadValue(s, ref i, depth + 1));\n                SkipSpace(s, ref i);\n                if (i >= s.Length) throw new FormatException(\"unexpected end\");\n                if (s[i] == ',') { i++; continue; }\n                if (s[i] == ']') { i++; return result; }\n                throw new FormatException(\"expected , or ]\");\n            }\n        }\n\n        static string ReadString(string s, ref int i)\n        {\n            var sb = new StringBuilder();\n            i++; // opening quote\n            while (true)\n            {\n                if (i >= s.Length) throw new FormatException(\"unterminated string\");\n                char c = s[i++];\n                if (c == '\"') return sb.ToString();\n                if (c != '\\\\') { sb.Append(c); continue; }\n                if (i >= s.Length) throw new FormatException(\"unterminated escape\");\n                char e = s[i++];\n                switch (e)\n                {\n                    case '\"': sb.Append('\"'); break;\n                    case '\\\\': sb.Append('\\\\'); break;\n                    case '/': sb.Append('/'); break;\n                    case 'b': sb.Append('\\b'); break;\n                    case 'f': sb.Append('\\f'); break;\n                    case 'n': sb.Append('\\n'); break;\n                    case 'r': sb.Append('\\r'); break;\n                    case 't': sb.Append('\\t'); break;\n                    case 'u':\n                        if (i + 4 > s.Length) throw new FormatException(\"bad unicode escape\");\n                        int code;\n                        if (!int.TryParse(s.Substring(i, 4), NumberStyles.HexNumber, CultureInfo.InvariantCulture, out code))\n                            throw new FormatException(\"bad unicode escape\");\n                        sb.Append((char)code);\n                        i += 4;\n                        break;\n                    default: throw new FormatException(\"bad escape\");\n                }\n            }\n        }\n\n        /// <summary>A string as a JSON literal, with everything that could break a one-line message escaped.</summary>\n        public static string Quote(string value)\n        {\n            if (value == null) return \"null\";\n            var sb = new StringBuilder(value.Length + 2);\n            sb.Append('\"');\n            foreach (char c in value)\n            {\n                switch (c)\n                {\n                    case '\"': sb.Append(\"\\\\\\\"\"); break;\n                    case '\\\\': sb.Append(\"\\\\\\\\\"); break;\n                    case '\\n': sb.Append(\"\\\\n\"); break;\n                    case '\\r': sb.Append(\"\\\\r\"); break;\n                    case '\\t': sb.Append(\"\\\\t\"); break;\n                    case '\\b': sb.Append(\"\\\\b\"); break;\n                    case '\\f': sb.Append(\"\\\\f\"); break;\n                    default:\n                        if (c < ' ' || c == '\\u2028' || c == '\\u2029') sb.Append(\"\\\\u\").Append(((int)c).ToString(\"x4\", CultureInfo.InvariantCulture));\n                        else sb.Append(c);\n                        break;\n                }\n            }\n            sb.Append('\"');\n            return sb.ToString();\n        }\n\n        public static string GetString(object obj, string key)\n        {\n            var d = obj as Dictionary<string, object>;\n            object v;\n            if (d == null || !d.TryGetValue(key, out v)) return null;\n            return v as string;\n        }\n    }\n\n    public sealed class ModelOption\n    {\n        public string Key;\n        public string Label;\n        public ModelOption(string key, string label) { Key = key; Label = label; }\n    }\n\n    /// <summary>The command line: `listen`, or `prompt --app=X --window-title=T --models=JSON --model=KEY`.</summary>\n    public sealed class HudArgs\n    {\n        public string Mode = \"prompt\";\n        public string App = \"Desktop\";\n        public string WindowTitle = \"\";\n        public List<ModelOption> Models = new List<ModelOption>();\n        public string ModelKey = \"\";\n        public string NodePath = \"\";\n        public string CliPath = \"\";\n        /// <summary>One-shot prompt: print the first request and exit, never reading the daemon's messages.</summary>\n        public bool Once;\n\n        public static HudArgs Parse(string[] args)\n        {\n            var result = new HudArgs();\n            if (args == null) return result;\n            foreach (string arg in args)\n            {\n                if (arg == null) continue;\n                if (arg == \"listen\") result.Mode = \"listen\";\n                else if (arg == \"supervise\") result.Mode = \"supervise\";\n                else if (arg == \"--once\") result.Once = true;\n                else if (arg.StartsWith(\"--app=\", StringComparison.Ordinal)) result.App = arg.Substring(6);\n                else if (arg.StartsWith(\"--window-title=\", StringComparison.Ordinal)) result.WindowTitle = arg.Substring(15);\n                else if (arg.StartsWith(\"--model=\", StringComparison.Ordinal)) result.ModelKey = arg.Substring(8);\n                else if (arg.StartsWith(\"--node=\", StringComparison.Ordinal)) result.NodePath = arg.Substring(7);\n                else if (arg.StartsWith(\"--cli=\", StringComparison.Ordinal)) result.CliPath = arg.Substring(6);\n                else if (arg.StartsWith(\"--models=\", StringComparison.Ordinal))\n                {\n                    var list = Json.Parse(arg.Substring(9)) as List<object>;\n                    if (list == null) continue;\n                    foreach (object item in list)\n                    {\n                        string key = Json.GetString(item, \"key\");\n                        string label = Json.GetString(item, \"label\");\n                        if (!string.IsNullOrEmpty(key) && !string.IsNullOrEmpty(label)) result.Models.Add(new ModelOption(key, label));\n                    }\n                }\n            }\n            if (result.App.Length == 0) result.App = \"Desktop\";\n            return result;\n        }\n    }\n\n    /// <summary>The lines this program prints for the daemon.</summary>\n    public static class Messages\n    {\n        public static string Submit(string query, string app, string windowTitle, string modelKey)\n        {\n            var sb = new StringBuilder();\n            sb.Append(\"{\\\"event\\\":\\\"submit\\\",\\\"query\\\":\").Append(Json.Quote(query));\n            sb.Append(\",\\\"app\\\":\").Append(Json.Quote(app));\n            if (!string.IsNullOrEmpty(windowTitle)) sb.Append(\",\\\"windowTitle\\\":\").Append(Json.Quote(windowTitle));\n            if (!string.IsNullOrEmpty(modelKey)) sb.Append(\",\\\"model\\\":\").Append(Json.Quote(modelKey));\n            sb.Append('}');\n            return sb.ToString();\n        }\n\n        public static string Model(string modelKey) { return \"{\\\"event\\\":\\\"model\\\",\\\"model\\\":\" + Json.Quote(modelKey) + \"}\"; }\n        public static string Stop() { return \"{\\\"event\\\":\\\"stop\\\"}\"; }\n        public static string Cancel() { return \"{\\\"event\\\":\\\"cancel\\\"}\"; }\n\n        public static string Hotkey(string app, string windowTitle)\n        {\n            return \"{\\\"event\\\":\\\"hotkey\\\",\\\"app\\\":\" + Json.Quote(app) + \",\\\"windowTitle\\\":\" + Json.Quote(windowTitle) + \"}\";\n        }\n\n        /// <summary>Tells the daemon which keys the hotkey ended up on (another program may hold the first choice).</summary>\n        public static string HotkeyReady(string keys) { return \"{\\\"event\\\":\\\"hotkey-ready\\\",\\\"keys\\\":\" + Json.Quote(keys) + \"}\"; }\n        public static string HotkeyFailed() { return \"{\\\"event\\\":\\\"hotkey-failed\\\"}\"; }\n    }\n\n    /// <summary>The supervisor's settings, written by `rh hud install` so the login entry itself stays short.</summary>\n    public sealed class SupervisorSettings\n    {\n        public string Node = \"\";\n        public string Cli = \"\";\n\n        public static SupervisorSettings Parse(string json)\n        {\n            var result = new SupervisorSettings();\n            object parsed = Json.Parse(json);\n            string node = Json.GetString(parsed, \"node\");\n            string cli = Json.GetString(parsed, \"cli\");\n            if (!string.IsNullOrEmpty(node)) result.Node = node;\n            if (!string.IsNullOrEmpty(cli)) result.Cli = cli;\n            return result;\n        }\n    }\n\n    public enum EntryKind { Goal, Step, Attention, Error, Answer, Note }\n\n    public enum Tone { Accent, Success, Warning, Danger }\n\n    public sealed class FeedEntry\n    {\n        public EntryKind Kind;\n        public string Text;\n        public FeedEntry(EntryKind kind, string text) { Kind = kind; Text = text; }\n    }\n\n    /// <summary>What the window should show after a message from the daemon.</summary>\n    public sealed class UpdateResult\n    {\n        public List<FeedEntry> Entries = new List<FeedEntry>();\n        public bool Ignored;\n        public bool GiveInputBack;\n    }\n\n    /// <summary>\n    /// The state of the progress window and how it follows the daemon's messages. The rules are those of the Mac window:\n    /// a finished task never gets its spinner back, a failed one gives the input back, and so on.\n    /// </summary>\n    public sealed class HudState\n    {\n        public bool IsWorking;\n        public bool IsExpanded;\n        public string StatusWord = \"\";\n        public Tone StatusTone = Tone.Accent;\n        public bool StopVisible;\n        public bool CopyVisible;\n        public string AnswerText = \"\";\n\n        /// <summary>The person pressed Enter on a request.</summary>\n        public void Submitted()\n        {\n            IsExpanded = true;\n            IsWorking = true;\n            StatusWord = \"Starting\";\n            StatusTone = Tone.Accent;\n            StopVisible = true;\n            CopyVisible = false;\n            AnswerText = \"\";\n        }\n\n        /// <summary>The person pressed Stop (or Esc while working).</summary>\n        public FeedEntry StopClicked()\n        {\n            IsWorking = false;\n            StatusWord = \"Stopped\";\n            StatusTone = Tone.Warning;\n            StopVisible = false;\n            return new FeedEntry(EntryKind.Note, \"Stopped.\");\n        }\n\n        /// <summary>\"READING\" in the protocol is \"Reading\" on screen.</summary>\n        public static string DisplayStatus(string raw)\n        {\n            if (string.IsNullOrEmpty(raw)) return \"\";\n            string lower = raw.ToLowerInvariant();\n            return char.ToUpperInvariant(lower[0]) + lower.Substring(1);\n        }\n\n        public UpdateResult Apply(string status, string text, string role)\n        {\n            var result = new UpdateResult();\n            string up = string.IsNullOrEmpty(status) ? \"WORKING\" : status.ToUpperInvariant();\n            string body = text == null ? \"\" : text;\n            if (up == \"COMPLETE\" || up == \"DONE\")\n            {\n                IsWorking = false;\n                StatusWord = \"Done\";\n                StatusTone = Tone.Success;\n                StopVisible = false;\n                string final = body.Trim();\n                string shown = final.Length == 0 ? \"Task completed successfully.\" : final;\n                result.Entries.Add(new FeedEntry(EntryKind.Answer, shown));\n                AnswerText = shown;\n                CopyVisible = AnswerText.Length > 0;\n                result.GiveInputBack = true;\n            }\n            else if (up == \"STOPPED\" || up == \"CANCELLED\")\n            {\n                if (IsWorking) result.Entries.Add(new FeedEntry(EntryKind.Note, body.Trim().Length == 0 ? \"Stopped.\" : body.Trim()));\n                IsWorking = false;\n                StatusWord = \"Stopped\";\n                StatusTone = Tone.Warning;\n                StopVisible = false;\n                result.GiveInputBack = true;\n            }\n            else if (up == \"FAILED\")\n            {\n                IsWorking = false;\n                StatusWord = \"Failed\";\n                StatusTone = Tone.Danger;\n                StopVisible = false;\n                result.Entries.Add(new FeedEntry(EntryKind.Error, body.Trim().Length == 0 ? \"The task failed.\" : body.Trim()));\n                result.GiveInputBack = true;\n            }\n            else if (up == \"ERROR\")\n            {\n                result.Entries.Add(new FeedEntry(EntryKind.Error, body.Trim().Length == 0 ? \"Something went wrong.\" : body.Trim()));\n            }\n            else if (body.Length == 0 && !IsWorking)\n            {\n                // a status word that arrives after the task ended must not bring the spinner back\n                result.Ignored = true;\n            }\n            else\n            {\n                IsWorking = true;\n                StatusWord = DisplayStatus(up);\n                StatusTone = Tone.Accent;\n                StopVisible = true;\n                CopyVisible = false;\n                if (body.Trim().Length > 0)\n                {\n                    bool attention = role == \"ATTENTION\" || role == \"PROBLEM\";\n                    result.Entries.Add(new FeedEntry(attention ? EntryKind.Attention : EntryKind.Step, body.Trim()));\n                }\n            }\n            return result;\n        }\n    }\n\n    public static class Links\n    {\n        /// <summary>Only web and mail links may be opened from the agent's text; a file path or a program must never be.</summary>\n        public static bool IsOpenable(string url)\n        {\n            if (string.IsNullOrEmpty(url)) return false;\n            Uri uri;\n            if (!Uri.TryCreate(url.Trim(), UriKind.Absolute, out uri)) return false;\n            string scheme = uri.Scheme.ToLowerInvariant();\n            return scheme == \"http\" || scheme == \"https\" || scheme == \"mailto\";\n        }\n    }\n\n    public static class AppNames\n    {\n        /// <summary>The name a person knows a program by, from its process name (\"msedge\" is Microsoft Edge).</summary>\n        public static string Friendly(string processName)\n        {\n            if (string.IsNullOrEmpty(processName)) return \"Desktop\";\n            string lower = processName.Trim().ToLowerInvariant();\n            if (lower.EndsWith(\".exe\", StringComparison.Ordinal)) lower = lower.Substring(0, lower.Length - 4);\n            switch (lower)\n            {\n                case \"chrome\": return \"Google Chrome\";\n                case \"msedge\": return \"Microsoft Edge\";\n                case \"firefox\": return \"Firefox\";\n                case \"brave\": return \"Brave Browser\";\n                case \"opera\": return \"Opera\";\n                case \"vivaldi\": return \"Vivaldi\";\n                case \"arc\": return \"Arc\";\n                case \"explorer\": return \"File Explorer\";\n                case \"notepad\": return \"Notepad\";\n                case \"winword\": return \"Microsoft Word\";\n                case \"excel\": return \"Microsoft Excel\";\n                case \"powerpnt\": return \"Microsoft PowerPoint\";\n                case \"outlook\": return \"Microsoft Outlook\";\n                case \"code\": return \"Visual Studio Code\";\n                case \"slack\": return \"Slack\";\n                case \"teams\":\n                case \"ms-teams\": return \"Microsoft Teams\";\n                case \"applicationframehost\": return \"Desktop\";\n                case \"searchhost\":\n                case \"startmenuexperiencehost\":\n                case \"shellexperiencehost\": return \"Desktop\";\n            }\n            return char.ToUpperInvariant(lower[0]) + lower.Substring(1);\n        }\n    }\n\n    public enum Mood { Idle, Typing, Working, Happy, Error, Stopped }\n\n    public enum Expression { Neutral, Listening, Happy, Content, Terminal, Focus, Thinking, Surprised, Sad, Error, Sleepy, Wink, Laugh, Smug }\n\n    public enum EyeShape { Open, ArcUp, ArcDown, ChevronRight, ChevronLeft, Underscore, Cross }\n\n    public enum MouthShape { Smile, Grin, O, Flat, Wave, Smirk }\n\n    /// <summary>What one expression looks like: the shape of each eye and of the mouth, and a few tweaks (same as the Mac HUD).</summary>\n    public sealed class FaceSpec\n    {\n        public EyeShape Left = EyeShape.Open;\n        public EyeShape Right = EyeShape.Open;\n        public double EyeWidth = 1;\n        public double EyeHeight = 1;\n        public double RightScale = 1;\n        /// <summary>Degrees; the left eye turns this way, the right one the opposite way.</summary>\n        public double Tilt;\n        /// <summary>How much of the eye is covered from the top.</summary>\n        public double Lid;\n        public MouthShape Mouth = MouthShape.Smile;\n        /// <summary>-1 frown ... 1 big smile.</summary>\n        public double Curve = 0.5;\n        public double MouthSize = 1;\n        /// <summary>Drawn in red instead of cyan.</summary>\n        public bool Warning;\n        public bool Zzz;\n        /// <summary>Where it looks whatever the cursor does (-1..1), or null.</summary>\n        public double? ForcedGazeX;\n        public double ForcedGazeY;\n\n        public static FaceSpec Of(Expression e)\n        {\n            var s = new FaceSpec();\n            switch (e)\n            {\n                case Expression.Listening: s.EyeWidth = 1.05; s.EyeHeight = 1.15; s.Curve = 0.65; break;\n                case Expression.Happy: s.Left = EyeShape.ArcUp; s.Right = EyeShape.ArcUp; s.Mouth = MouthShape.Grin; s.MouthSize = 0.9; break;\n                case Expression.Content: s.Left = EyeShape.ArcDown; s.Right = EyeShape.ArcDown; s.Curve = 0.8; break;\n                case Expression.Terminal: s.Left = EyeShape.ChevronRight; s.Right = EyeShape.Underscore; s.Curve = 0.25; s.MouthSize = 0.8; break;\n                case Expression.Focus: s.EyeHeight = 0.55; s.Mouth = MouthShape.Flat; break;\n                case Expression.Thinking: s.EyeWidth = 0.9; s.RightScale = 1.25; s.Mouth = MouthShape.Wave; s.MouthSize = 0.95; s.ForcedGazeX = 0.8; s.ForcedGazeY = -0.9; break;\n                case Expression.Surprised: s.EyeHeight = 1.4; s.EyeWidth = 1.12; s.Mouth = MouthShape.O; break;\n                case Expression.Sad: s.EyeHeight = 0.9; s.Tilt = 15; s.Curve = -0.7; break;\n                case Expression.Error: s.Left = EyeShape.Cross; s.Right = EyeShape.Cross; s.Mouth = MouthShape.Wave; s.Warning = true; break;\n                case Expression.Sleepy: s.Left = EyeShape.ArcDown; s.Right = EyeShape.ArcDown; s.Mouth = MouthShape.O; s.MouthSize = 0.45; s.Zzz = true; break;\n                case Expression.Wink: s.Right = EyeShape.ArcUp; s.Curve = 0.85; break;\n                case Expression.Laugh: s.Left = EyeShape.ChevronRight; s.Right = EyeShape.ChevronLeft; s.Mouth = MouthShape.Grin; s.MouthSize = 1.15; break;\n                case Expression.Smug: s.Lid = 0.5; s.Mouth = MouthShape.Smirk; s.Curve = 0.7; s.ForcedGazeX = 0.9; s.ForcedGazeY = 0; break;\n            }\n            return s;\n        }\n    }\n\n    /// <summary>Where things are on the mascot's pictures, as fractions of the picture (assets/mascot/meta.json). Same numbers as `Face` in the Mac HUD.</summary>\n    public static class Face\n    {\n        public const double VisorX0 = 0.2065, VisorY0 = 0.2192, VisorX1 = 0.6877, VisorY1 = 0.5100;\n        public const double EyeLeftX = 0.3261, EyeRightX = 0.5464, EyeY = 0.3611;\n        public const double EyeW = 0.0620, EyeH = 0.0760;\n        public const double MouthX = 0.4341, MouthY = 0.4258;\n        public const double PivotX = 0.4884, PivotY = 0.5466;\n        public const double HeadShiftX = 0.035, HeadShiftY = 0.018, HeadTilt = 7.0;\n        public const double GazeShiftX = 0.05, GazeShiftY = 0.03;\n    }\n\n    /// <summary>What the mascot looks like right now (one tick): the face, where it looks, how the head sits.</summary>\n    public sealed class MascotPose\n    {\n        public Expression Shown = Expression.Neutral;\n        public FaceSpec Spec = FaceSpec.Of(Expression.Neutral);\n        public double Fade = 1;\n        /// <summary>Eyes: 1 open ... 0 shut (a blink).</summary>\n        public double Openness = 1;\n        public double GazeX, GazeY;\n        /// <summary>The head's offset as a fraction of the picture, and its tilt in degrees (clockwise is positive).</summary>\n        public double HeadX, HeadY, HeadTilt;\n        public bool CursorOn = true;\n        public double ZPhase;\n\n        /// <summary>Changes when anything that is drawn changes (so an idle mascot costs nothing).</summary>\n        public string Key()\n        {\n            return Shown + \"|\" + (int)(Fade * 10) + \"|\" + (int)(Openness * 10) + \"|\" + (int)(GazeX * 20) + \"|\" + (int)(GazeY * 20) + \"|\" +\n                   (int)(HeadX * 4000) + \"|\" + (int)(HeadY * 4000) + \"|\" + (int)(HeadTilt * 10) + \"|\" + CursorOn + \"|\" + (Spec.Zzz ? (int)(ZPhase * 30) : 0);\n        }\n    }\n\n    /// <summary>\n    /// What the mascot feels and does: the same rules as the Mac window. It follows the cursor with its eyes and its whole\n    /// head, blinks, now and then makes a face when idle, looks down while someone types, shows a terminal prompt in its\n    /// eyes while a task runs, and smiles, frowns or dozes when it ends. One tick is 50 ms.\n    /// </summary>\n    public sealed class MascotBrain\n    {\n        static readonly double[] BlinkOpenness = new double[] { 0.45, 0.06, 0.45 };\n        static readonly int[] HopTable = new int[] { 0, 6, 11, 14, 11, 6, 0, 3, 5, 3, 0 };\n        static readonly Expression[] Ambient = new Expression[] { Expression.Content, Expression.Smug, Expression.Wink, Expression.Laugh, Expression.Content };\n\n        readonly Random rng;\n        readonly List<KeyValuePair<Expression, int>> reactions = new List<KeyValuePair<Expression, int>>();\n        readonly MascotPose pose = new MascotPose();\n        int tick;\n        int reactionLeft;\n        int happyUntil;\n        int hopStart = -1;\n        int nextBlink = 50;\n        int blinkStart = -1;\n        int nextAmbient = 200;\n        int ambientUntil;\n        bool hasAmbient;\n        Expression ambient = Expression.Neutral;\n        int nextThought = 150;\n        int thoughtUntil;\n        int lastActivity;\n        Expression wanted = Expression.Neutral;\n        Mood mood = Mood.Idle;\n\n        /// <summary>How much has been typed (a long request makes it concentrate).</summary>\n        public int TypedLength;\n\n        /// <param name=\"seed\">for the timing of blinks and faces; tests pass a fixed one</param>\n        public MascotBrain(int seed)\n        {\n            rng = new Random(seed);\n        }\n\n        public Mood Current { get { return mood; } }\n\n        /// <summary>The pose as of the last tick.</summary>\n        public MascotPose Latest() { return pose; }\n\n        public void SetMood(Mood next)\n        {\n            if (next == mood) return;\n            mood = next;\n            lastActivity = tick;\n            if (next == Mood.Happy)\n            {\n                happyUntil = tick + 80;\n                hopStart = tick;\n            }\n        }\n\n        /// <summary>A click or a hello: a short run of faces ahead of whatever the mood says.</summary>\n        public void Play(Expression first, int firstTicks, Expression second, int secondTicks)\n        {\n            reactions.Clear();\n            reactions.Add(new KeyValuePair<Expression, int>(first, firstTicks));\n            if (secondTicks > 0) reactions.Add(new KeyValuePair<Expression, int>(second, secondTicks));\n            reactionLeft = firstTicks;\n        }\n\n        /// <summary>A click: jump in surprise, then laugh.</summary>\n        public void Poke()\n        {\n            Play(Expression.Surprised, 8, Expression.Laugh, 26);\n            hopStart = tick;\n        }\n\n        public static Mood MoodFor(bool working, Tone tone)\n        {\n            if (working) return Mood.Working;\n            switch (tone)\n            {\n                case Tone.Success: return Mood.Happy;\n                case Tone.Danger: return Mood.Error;\n                case Tone.Warning: return Mood.Stopped;\n                default: return Mood.Idle;\n            }\n        }\n\n        /// <summary>How high (in 96-dpi pixels) the little jump after a finished task has lifted it right now.</summary>\n        public int HopOffset()\n        {\n            if (hopStart < 0) return 0;\n            int i = tick - hopStart;\n            if (i >= HopTable.Length)\n            {\n                hopStart = -1;\n                return 0;\n            }\n            return HopTable[i];\n        }\n\n        /// <summary>\n        /// Advances one tick. (lookX, lookY) is where the cursor is from the eyes, -1..1 each way (y grows downward);\n        /// `activity` says the cursor moved since the last tick.\n        /// </summary>\n        public MascotPose Step(double lookX, double lookY, bool activity)\n        {\n            tick++;\n            if (activity) lastActivity = tick;\n            if (mood == Mood.Happy && tick >= happyUntil) mood = Mood.Idle;\n            wanted = Wanted();\n            FaceSpec spec = FaceSpec.Of(pose.Shown);\n\n            double gazeX = lookX, gazeY = lookY;\n            // typing: it reads along the text, from left to right as the request grows, looking down at it\n            if (mood == Mood.Typing) { gazeX = Math.Min(0.8, -0.7 + TypedLength * 0.03); gazeY = 0.9; }\n            if (spec.ForcedGazeX.HasValue) { gazeX = spec.ForcedGazeX.Value; gazeY = spec.ForcedGazeY; }\n            pose.GazeX += (gazeX - pose.GazeX) * 0.4;\n            pose.GazeY += (gazeY - pose.GazeY) * 0.4;\n\n            double headX = lookX, headY = lookY, tiltExtra = 0;\n            if (mood == Mood.Typing) { headX = lookX * 0.3; headY = 0.7; }\n            if (pose.Shown == Expression.Sleepy) { headX = 0; headY = 1.2; tiltExtra = 5; }\n            if (pose.Shown == Expression.Thinking) tiltExtra = -5;\n            pose.HeadX += (headX * Face.HeadShiftX - pose.HeadX) * 0.25;\n            pose.HeadY += (headY * Face.HeadShiftY - pose.HeadY) * 0.25;\n            pose.HeadTilt += ((headX * Face.HeadTilt + tiltExtra) - pose.HeadTilt) * 0.25;\n\n            // changing the face: the old one fades out, the new one fades in\n            if (pose.Shown != wanted)\n            {\n                pose.Fade -= 0.35;\n                if (pose.Fade <= 0)\n                {\n                    pose.Shown = wanted;\n                    pose.Fade = 0;\n                }\n            }\n            else if (pose.Fade < 1)\n            {\n                pose.Fade = Math.Min(1, pose.Fade + 0.35);\n            }\n\n            // blinking\n            pose.Openness = 1;\n            if (blinkStart < 0 && tick >= nextBlink) blinkStart = tick;\n            if (blinkStart >= 0)\n            {\n                int i = (tick - blinkStart) / 2;\n                if (i < BlinkOpenness.Length)\n                {\n                    pose.Openness = BlinkOpenness[i];\n                }\n                else\n                {\n                    blinkStart = -1;\n                    nextBlink = tick + (rng.Next(5) == 0 ? 7 : 50 + rng.Next(81));\n                }\n            }\n            pose.Spec = FaceSpec.Of(pose.Shown);\n            pose.CursorOn = (tick / 8) % 2 == 0;\n            pose.ZPhase = (tick % 60) / 60.0;\n            return pose;\n        }\n\n        /// <summary>A reaction first, then the mood, then (when idle) a little personality.</summary>\n        Expression Wanted()\n        {\n            if (reactions.Count > 0)\n            {\n                Expression current = reactions[0].Key;\n                if (--reactionLeft <= 0)\n                {\n                    reactions.RemoveAt(0);\n                    if (reactions.Count > 0) reactionLeft = reactions[0].Value;\n                }\n                return current;\n            }\n            switch (mood)\n            {\n                case Mood.Working:\n                    if (tick >= nextThought)\n                    {\n                        thoughtUntil = tick + 36;\n                        nextThought = thoughtUntil + 100 + rng.Next(121);\n                    }\n                    return tick < thoughtUntil ? Expression.Thinking : Expression.Terminal;\n                case Mood.Happy: return Expression.Happy;\n                case Mood.Error: return Expression.Error;\n                case Mood.Stopped: return Expression.Sleepy;\n                case Mood.Typing: return TypedLength > 90 ? Expression.Focus : Expression.Listening;\n            }\n            if (tick - lastActivity > 1000) return Expression.Sleepy;\n            if (hasAmbient && tick < ambientUntil) return ambient;\n            hasAmbient = false;\n            if (tick >= nextAmbient)\n            {\n                ambient = Ambient[rng.Next(Ambient.Length)];\n                hasAmbient = true;\n                ambientUntil = tick + 20 + rng.Next(13);\n                nextAmbient = ambientUntil + 160 + rng.Next(141);\n                return ambient;\n            }\n            return Expression.Neutral;\n        }\n    }\n\n    // ---- the card stack (progress view) -------------------------------------------------------\n\n    public enum CardKind { Request, Step, Note, Attention, Error, Answer }\n\n    /// <summary>One card in the stack: your request (with its live status), a step, a problem, a note or the answer.</summary>\n    public sealed class Card\n    {\n        public CardKind Kind;\n        public string Title = \"\";\n        public string Body = \"\";\n        /// <summary>A step that is still happening shows a turning ring instead of a check.</summary>\n        public bool InProgress;\n        /// <summary>Set by the view once the text is measured; Y is then the card's top inside the stack.</summary>\n        public int Height;\n        public int Y;\n        public int StartedTick;\n        public int FinishedSeconds = -1;\n        public bool Working;\n        public bool Latest;\n    }\n\n    /// <summary>The cards and the rules around them. The view measures and draws; everything that decides lives here.</summary>\n    public sealed class CardStack\n    {\n        public const int Gap = 12;\n        public const int Tail = 6;\n        public const int ToolbarHeight = 36;\n        public const int NewestClear = 3;\n\n        public readonly List<Card> Cards = new List<Card>();\n        Card active;\n        Card request;\n\n        public Card Request { get { return request; } }\n        public Card Answer;\n\n        public static CardKind KindFor(EntryKind kind)\n        {\n            switch (kind)\n            {\n                case EntryKind.Goal: return CardKind.Request;\n                case EntryKind.Step: return CardKind.Step;\n                case EntryKind.Attention: return CardKind.Attention;\n                case EntryKind.Error: return CardKind.Error;\n                case EntryKind.Answer: return CardKind.Answer;\n                default: return CardKind.Note;\n            }\n        }\n\n        /// <summary>Adds the card for a new entry. A new card means the step that was happening is done.</summary>\n        public Card Add(FeedEntry entry, int nowTick, bool working)\n        {\n            FinishActive();\n            var card = new Card();\n            card.Kind = KindFor(entry.Kind);\n            card.StartedTick = nowTick;\n            if (card.Kind == CardKind.Answer)\n            {\n                card.Title = \"Done\";\n                card.Body = entry.Text;\n                Answer = card;\n            }\n            else\n            {\n                card.Title = entry.Text;\n            }\n            if (card.Kind == CardKind.Step)\n            {\n                card.InProgress = true;\n                active = card;\n            }\n            if (card.Kind == CardKind.Request)\n            {\n                // the older request keeps its words but gives up the buttons\n                if (request != null) { request.Latest = false; request.Working = false; }\n                request = card;\n                card.Latest = true;\n                card.Working = working;\n            }\n            Cards.Add(card);\n            return card;\n        }\n\n        public void FinishActive()\n        {\n            if (active != null) active.InProgress = false;\n            active = null;\n        }\n\n        public void Clear()\n        {\n            Cards.Clear();\n            active = null;\n            request = null;\n            Answer = null;\n        }\n\n        /// <summary>The request card follows the task: working, then done (remembering how long it took).</summary>\n        public void SetWorking(bool working, int nowTick, int ticksPerSecond)\n        {\n            if (request == null) return;\n            if (request.Working && !working) request.FinishedSeconds = (nowTick - request.StartedTick) / ticksPerSecond;\n            if (!request.Working && working) request.FinishedSeconds = -1;\n            request.Working = working;\n            if (!working) FinishActive();\n        }\n\n        /// <summary>Stacks the cards from the top, one gap apart; returns the height of the whole stack.</summary>\n        public int Layout()\n        {\n            int y = 0;\n            foreach (Card card in Cards)\n            {\n                card.Y = y;\n                y += card.Height + Gap;\n            }\n            return Cards.Count == 0 ? 0 : y - Gap + Tail;\n        }\n\n        /// <summary>Cards older than the newest few are quieter until the mouse comes to read them.</summary>\n        public static bool IsDimmed(int index, int count, bool hovering)\n        {\n            return !hovering && count - 1 - index >= NewestClear;\n        }\n\n        /// <summary>The most the stack may take: what is left on screen, never under 200 and never over 600.</summary>\n        public static int MaxHeight(int room)\n        {\n            return Math.Max(200, Math.Min(600, room));\n        }\n\n        public static int ClampScroll(int offset, int content, int viewport)\n        {\n            return Math.Max(0, Math.Min(offset, Math.Max(0, content - viewport)));\n        }\n\n        /// <summary>Opacity (0..1) of the top edge: only fades when cards are scrolled up out of sight.</summary>\n        public static double TopFade(int offset)\n        {\n            return 1 - Math.Min(1, Math.Max(0, offset) / 24.0);\n        }\n\n        /// <summary>Opacity (0..1) of the bottom edge: only fades while more cards wait below.</summary>\n        public static double BottomFade(int offset, int content, int viewport)\n        {\n            int below = Math.Max(0, content - viewport - offset);\n            return 1 - Math.Min(1, below / 24.0);\n        }\n\n        /// <summary>\"Working...\" then the time once it is worth saying (\"Working... - 12s\").</summary>\n        public static string StatusLine(string word, bool working, int dots, int seconds)\n        {\n            string suffix = working ? new string('.', ((dots % 4) + 4) % 4) : \"\";\n            string time = seconds >= 3 ? \"  \\u00B7  \" + seconds + \"s\" : \"\";\n            return word + suffix + time;\n        }\n    }\n}\n","Hud.cs":"// Remote Hands Windows HUD: the hotkey listener, the prompt/progress window, and the login supervisor.\n// It speaks the same JSON-lines protocol as the Mac HUD (see HudLogic.cs for the lines) and is built on the user's PC by\n// the compiler that ships with Windows (csc.exe, C# 5): no ?., $\"\", nameof or expression bodies.\n//\n//   rh-hud.exe listen                      prints {\"event\":\"hotkey\",\"app\":...,\"windowTitle\":...} when Ctrl+Shift+Space is pressed\n//   rh-hud.exe prompt --app=... [--models=JSON --model=KEY]   the window: prints submit/stop/cancel/model lines, reads updates\n//   rh-hud.exe supervise --node=... --cli=...   keeps `node cli hud listen` running, with no console window\nusing System;\nusing System.Collections.Generic;\nusing System.Diagnostics;\nusing System.Drawing;\nusing System.Drawing.Drawing2D;\nusing System.Drawing.Imaging;\nusing System.IO;\nusing System.Runtime.InteropServices;\nusing System.Text;\nusing System.Threading;\nusing System.Windows.Forms;\n\nnamespace RemoteHands\n{\n    static class Native\n    {\n        public const int WM_HOTKEY = 0x0312;\n        public const int WM_NCLBUTTONDOWN = 0x00A1;\n        public const int HTCAPTION = 2;\n        public const int EM_SETCUEBANNER = 0x1501;\n        public const uint MOD_ALT = 0x1, MOD_CONTROL = 0x2, MOD_SHIFT = 0x4, MOD_NOREPEAT = 0x4000;\n        public const uint VK_SPACE = 0x20;\n        public static readonly IntPtr HWND_MESSAGE = new IntPtr(-3);\n\n        [DllImport(\"user32.dll\", SetLastError = true)] public static extern bool RegisterHotKey(IntPtr hWnd, int id, uint fsModifiers, uint vk);\n        [DllImport(\"user32.dll\", SetLastError = true)] public static extern bool UnregisterHotKey(IntPtr hWnd, int id);\n        [DllImport(\"user32.dll\")] public static extern IntPtr GetForegroundWindow();\n        [DllImport(\"user32.dll\")] public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint processId);\n        [DllImport(\"user32.dll\", CharSet = CharSet.Unicode)] public static extern int GetWindowText(IntPtr hWnd, StringBuilder text, int count);\n        [DllImport(\"user32.dll\")] public static extern bool SetForegroundWindow(IntPtr hWnd);\n        [DllImport(\"user32.dll\")] public static extern bool AllowSetForegroundWindow(int processId);\n        [DllImport(\"user32.dll\")] public static extern void keybd_event(byte vk, byte scan, uint flags, UIntPtr extra);\n        [DllImport(\"user32.dll\")] public static extern bool ReleaseCapture();\n        [DllImport(\"user32.dll\")] public static extern bool SetProcessDPIAware();\n        [DllImport(\"user32.dll\", CharSet = CharSet.Unicode)] public static extern IntPtr SendMessage(IntPtr hWnd, int msg, IntPtr wParam, string lParam);\n        [DllImport(\"user32.dll\")] public static extern IntPtr SendMessage(IntPtr hWnd, int msg, IntPtr wParam, IntPtr lParam);\n        [DllImport(\"gdi32.dll\")] public static extern IntPtr CreateRoundRectRgn(int x1, int y1, int x2, int y2, int cx, int cy);\n\n        // the mascot's see-through window\n        [StructLayout(LayoutKind.Sequential)] public struct POINT { public int X, Y; }\n        [StructLayout(LayoutKind.Sequential)] public struct SIZE { public int cx, cy; }\n        [StructLayout(LayoutKind.Sequential, Pack = 1)] public struct BLENDFUNCTION { public byte BlendOp, BlendFlags, SourceConstantAlpha, AlphaFormat; }\n        [DllImport(\"user32.dll\", SetLastError = true)] public static extern bool UpdateLayeredWindow(IntPtr hwnd, IntPtr hdcDst, ref POINT pptDst, ref SIZE psize, IntPtr hdcSrc, ref POINT pptSrc, int crKey, ref BLENDFUNCTION pblend, int dwFlags);\n        [DllImport(\"user32.dll\")] public static extern IntPtr GetDC(IntPtr hWnd);\n        [DllImport(\"user32.dll\")] public static extern int ReleaseDC(IntPtr hWnd, IntPtr hDC);\n        [DllImport(\"gdi32.dll\")] public static extern IntPtr CreateCompatibleDC(IntPtr hDC);\n        [DllImport(\"gdi32.dll\")] public static extern bool DeleteDC(IntPtr hdc);\n        [DllImport(\"gdi32.dll\")] public static extern IntPtr SelectObject(IntPtr hDC, IntPtr hObject);\n        [DllImport(\"gdi32.dll\")] public static extern bool DeleteObject(IntPtr hObject);\n\n        /// <summary>\n        /// Brings the window to the front and gives it the keyboard. The hotkey listener first allows any program to do this\n        /// (AllowSetForegroundWindow); if the system still refuses, one Alt key tap is the documented way to make it accept.\n        /// Nothing here waits on another program's window, so a hung application cannot freeze the prompt.\n        /// </summary>\n        public static void ForceForeground(IntPtr handle)\n        {\n            try\n            {\n                SetForegroundWindow(handle);\n                if (GetForegroundWindow() == handle) return;\n                keybd_event(0x12, 0, 0, UIntPtr.Zero);   // Alt down\n                keybd_event(0x12, 0, 2, UIntPtr.Zero);   // Alt up\n                SetForegroundWindow(handle);\n            }\n            catch (Exception)\n            {\n                // the window still shows; the person can click it\n            }\n        }\n    }\n\n    static class Theme\n    {\n        public static readonly Color Background = Color.Black;\n        public static readonly Color Border = Color.FromArgb(36, 36, 36);\n        public static readonly Color Divider = Color.FromArgb(26, 26, 26);\n        public static readonly Color Field = Color.FromArgb(23, 23, 23);\n        public static readonly Color Text = Color.FromArgb(245, 245, 245);\n        public static readonly Color Secondary = Color.FromArgb(163, 163, 163);\n        public static readonly Color Tertiary = Color.FromArgb(112, 112, 112);\n        public static readonly Color Accent = Color.FromArgb(97, 163, 255);\n        public static readonly Color Success = Color.FromArgb(82, 219, 143);\n        public static readonly Color Warning = Color.FromArgb(255, 194, 77);\n        public static readonly Color Danger = Color.FromArgb(255, 112, 112);\n        public static readonly Color ButtonFill = Color.FromArgb(31, 31, 31);\n        /// <summary>The chat pill and the tags under it, and the send button.</summary>\n        public static readonly Color Pill = Color.FromArgb(29, 29, 29);\n        public static readonly Color PillBorder = Color.FromArgb(61, 61, 61);\n        public static readonly Color Send = Color.FromArgb(56, 107, 245);\n\n        public static Color ForTone(Tone tone)\n        {\n            switch (tone)\n            {\n                case Tone.Success: return Success;\n                case Tone.Warning: return Warning;\n                case Tone.Danger: return Danger;\n                default: return Accent;\n            }\n        }\n    }\n\n    /// <summary>One place for the lines that go to the daemon (UTF-8, one line each, flushed at once).</summary>\n    static class Wire\n    {\n        static readonly object gate = new object();\n        static StreamWriter output;\n\n        public static void Send(string line)\n        {\n            lock (gate)\n            {\n                try\n                {\n                    if (output == null)\n                    {\n                        output = new StreamWriter(Console.OpenStandardOutput(), new UTF8Encoding(false));\n                        output.AutoFlush = true;\n                        output.NewLine = \"\\n\";\n                    }\n                    output.WriteLine(line);\n                }\n                catch (Exception)\n                {\n                    // the daemon went away; the window closes when its input ends\n                }\n            }\n        }\n\n        public static StreamReader Input()\n        {\n            return new StreamReader(Console.OpenStandardInput(), new UTF8Encoding(false));\n        }\n    }\n\n    sealed class Dpi\n    {\n        public static float Factor = 1.0f;\n        public static void Init()\n        {\n            try\n            {\n                using (var g = Graphics.FromHwnd(IntPtr.Zero)) Factor = g.DpiX / 96.0f;\n            }\n            catch (Exception)\n            {\n                Factor = 1.0f;\n            }\n            if (Factor < 1.0f) Factor = 1.0f;\n        }\n        public static int S(int value) { return (int)Math.Round(value * Factor); }\n    }\n\n    /// <summary>A flat rounded button that never takes focus from the text box.</summary>\n    sealed class PillButton : Button\n    {\n        public PillButton(string text, Color fore, Color fill)\n        {\n            FlatStyle = FlatStyle.Flat;\n            FlatAppearance.BorderSize = 0;\n            FlatAppearance.MouseOverBackColor = Color.FromArgb(48, 48, 48);\n            FlatAppearance.MouseDownBackColor = Color.FromArgb(60, 60, 60);\n            BackColor = fill;\n            ForeColor = fore;\n            Text = text;\n            Font = new Font(\"Segoe UI Semibold\", 9.5f);\n            Cursor = Cursors.Hand;\n            TabStop = false;\n            UseVisualStyleBackColor = false;\n            SizeChanged += delegate { Round(); };\n        }\n\n        protected override bool ShowFocusCues { get { return false; } }\n\n        void Round()\n        {\n            if (Width <= 0 || Height <= 0) return;\n            Region = Region.FromHrgn(Native.CreateRoundRectRgn(0, 0, Width + 1, Height + 1, Height, Height));\n        }\n    }\n\n    sealed class RoundPanel : Panel\n    {\n        public int Radius = 12;\n        public RoundPanel()\n        {\n            DoubleBuffered = true;\n            BackColor = Theme.Background;\n        }\n        protected override void OnPaint(PaintEventArgs e)\n        {\n            e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;\n            using (var path = Shapes.Rounded(new Rectangle(0, 0, Width - 1, Height - 1), Radius))\n            using (var fill = new SolidBrush(Theme.Field))\n            using (var pen = new Pen(Theme.Divider))\n            {\n                e.Graphics.FillPath(fill, path);\n                e.Graphics.DrawPath(pen, path);\n            }\n        }\n    }\n\n    static class Shapes\n    {\n        public static GraphicsPath Rounded(Rectangle r, int radius)\n        {\n            int d = Math.Max(2, radius * 2);\n            var path = new GraphicsPath();\n            path.AddArc(r.X, r.Y, d, d, 180, 90);\n            path.AddArc(r.Right - d, r.Y, d, d, 270, 90);\n            path.AddArc(r.Right - d, r.Bottom - d, d, d, 0, 90);\n            path.AddArc(r.X, r.Bottom - d, d, d, 90, 90);\n            path.CloseFigure();\n            return path;\n        }\n    }\n\n    /// <summary>The words in the prompt window, in one place so they are easy to change.</summary>\n    static class Copy\n    {\n        public const string Placeholder = \"Start a new task\\u2026\";\n    }\n\n    /// <summary>A round button with a drawn glyph: the send arrow (dim until there is something to send) or the model sparkle.</summary>\n    sealed class RoundButton : Button\n    {\n        public enum Glyphs { Arrow, Sparkle }\n\n        bool ready;\n        readonly Glyphs glyph;\n        public bool Outlined;\n\n        public RoundButton(Glyphs glyph)\n        {\n            this.glyph = glyph;\n            FlatStyle = FlatStyle.Flat;\n            FlatAppearance.BorderSize = 0;\n            FlatAppearance.MouseOverBackColor = Theme.Pill;\n            FlatAppearance.MouseDownBackColor = Theme.Pill;\n            BackColor = Theme.Pill;\n            Cursor = Cursors.Hand;\n            TabStop = false;\n            UseVisualStyleBackColor = false;\n            SizeChanged += delegate { Round(); };\n        }\n\n        public bool Ready\n        {\n            get { return ready; }\n            set\n            {\n                if (ready == value) return;\n                ready = value;\n                Invalidate();\n            }\n        }\n\n        protected override bool ShowFocusCues { get { return false; } }\n\n        void Round()\n        {\n            if (Width <= 0 || Height <= 0) return;\n            Region = Region.FromHrgn(Native.CreateRoundRectRgn(0, 0, Width + 1, Height + 1, Width, Height));\n        }\n\n        protected override void OnPaint(PaintEventArgs e)\n        {\n            e.Graphics.Clear(Theme.Pill);\n            e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;\n            float cx = Width / 2f, cy = Height / 2f;\n            if (glyph == Glyphs.Sparkle)\n            {\n                if (Outlined)\n                {\n                    using (var ring = new Pen(Theme.PillBorder)) e.Graphics.DrawEllipse(ring, 0, 0, Width - 1, Height - 1);\n                }\n                float r = Width * 0.21f, k = r * 0.12f;\n                using (var star = new GraphicsPath())\n                using (var brush = new SolidBrush(Theme.Secondary))\n                {\n                    star.AddBezier(new PointF(cx, cy - r), new PointF(cx + k, cy - k), new PointF(cx + k, cy - k), new PointF(cx + r, cy));\n                    star.AddBezier(new PointF(cx + r, cy), new PointF(cx + k, cy + k), new PointF(cx + k, cy + k), new PointF(cx, cy + r));\n                    star.AddBezier(new PointF(cx, cy + r), new PointF(cx - k, cy + k), new PointF(cx - k, cy + k), new PointF(cx - r, cy));\n                    star.AddBezier(new PointF(cx - r, cy), new PointF(cx - k, cy - k), new PointF(cx - k, cy - k), new PointF(cx, cy - r));\n                    star.CloseFigure();\n                    e.Graphics.FillPath(brush, star);\n                }\n                return;\n            }\n            Color fill = ready ? Theme.Send : Color.FromArgb(40, 58, 108);\n            Color arrow = ready ? Color.White : Color.FromArgb(170, 180, 205);\n            using (var brush = new SolidBrush(fill)) e.Graphics.FillEllipse(brush, 0, 0, Width - 1, Height - 1);\n            using (var pen = new Pen(arrow, Dpi.S(2)))\n            {\n                pen.StartCap = LineCap.Round;\n                pen.EndCap = LineCap.Round;\n                pen.LineJoin = LineJoin.Round;\n                float r = Width * 0.25f;\n                e.Graphics.DrawLine(pen, cx, cy + r, cx, cy - r);\n                e.Graphics.DrawLines(pen, new PointF[] { new PointF(cx - r, cy), new PointF(cx, cy - r), new PointF(cx + r, cy) });\n            }\n        }\n    }\n\n    /// <summary>\n    /// The mascot: a window of its own with per-pixel transparency, standing above the prompt (or in the corner of the\n    /// progress card). The body and the head are two pictures (the folder of PNGs the daemon writes, see assets/mascot);\n    /// the head moves and tilts on the neck toward the cursor, and the face is drawn here, in code, on its dark screen.\n    /// MascotBrain decides what it does. Without the pictures it is simply not shown.\n    /// </summary>\n    sealed class MascotForm : Form\n    {\n        readonly MascotBrain brain;\n        readonly System.Windows.Forms.Timer timer = new System.Windows.Forms.Timer();\n        readonly string dir;\n        Bitmap bodySource, headSource, bodyScaled, headScaled, canvas;\n        int width, height, centerX, bottomY, bobPixels, ticks;\n        string drawnKey = \"\";\n        Point lastCursor;\n        public readonly bool Available;\n        public readonly double Aspect;\n        /// <summary>Raised when \"Close\" is picked from the right-click menu.</summary>\n        public Action CloseRequested;\n        readonly ContextMenuStrip menu = new ContextMenuStrip();\n\n        public MascotForm(string dir)\n        {\n            this.dir = dir;\n            brain = new MascotBrain(Environment.TickCount);\n            FormBorderStyle = FormBorderStyle.None;\n            ShowInTaskbar = false;\n            TopMost = true;\n            StartPosition = FormStartPosition.Manual;\n            bodySource = LoadPicture(\"body\");\n            headSource = LoadPicture(\"head\");\n            if (bodySource != null && headSource != null && bodySource.Size == headSource.Size)\n            {\n                Available = true;\n                Aspect = (double)bodySource.Width / bodySource.Height;\n            }\n            timer.Interval = 50;\n            timer.Tick += delegate { Tick(); };\n            var close = new ToolStripMenuItem(\"Close\");\n            close.Click += delegate { if (CloseRequested != null) CloseRequested(); };\n            menu.Items.Add(close);\n            MouseUp += delegate(object sender, MouseEventArgs e)\n            {\n                if (e.Button == MouseButtons.Right) menu.Show(Cursor.Position);\n            };\n        }\n\n        protected override bool ShowWithoutActivation { get { return true; } }\n\n        protected override CreateParams CreateParams\n        {\n            get\n            {\n                var cp = base.CreateParams;\n                // layered (per-pixel alpha: clear pixels pass clicks through), never takes focus, no taskbar button\n                cp.ExStyle |= 0x00080000 | 0x08000000 | 0x00000080;\n                return cp;\n            }\n        }\n\n        Bitmap LoadPicture(string name)\n        {\n            try\n            {\n                string file = Path.Combine(dir, name + \".png\");\n                if (!File.Exists(file)) return null;\n                using (var stream = new MemoryStream(File.ReadAllBytes(file)))\n                using (var image = Image.FromStream(stream))\n                {\n                    return new Bitmap(image);\n                }\n            }\n            catch (Exception)\n            {\n                return null; // a missing or broken picture: no mascot\n            }\n        }\n\n        static Bitmap Scale(Bitmap source, int w, int h)\n        {\n            var result = new Bitmap(w, h, PixelFormat.Format32bppArgb);\n            using (var g = Graphics.FromImage(result))\n            {\n                g.InterpolationMode = InterpolationMode.HighQualityBicubic;\n                g.PixelOffsetMode = PixelOffsetMode.HighQuality;\n                g.DrawImage(source, new Rectangle(0, 0, w, h));\n            }\n            return result;\n        }\n\n        /// <summary>Stand with its feet at (centerX, bottomY) on the screen, `h` pixels tall.</summary>\n        public void Stand(int centerXPixels, int bottomYPixels, int h)\n        {\n            if (!Available) return;\n            centerX = centerXPixels;\n            bottomY = bottomYPixels;\n            if (h != height)\n            {\n                height = h;\n                width = (int)Math.Round(h * Aspect);\n                if (bodyScaled != null) bodyScaled.Dispose();\n                if (headScaled != null) headScaled.Dispose();\n                if (canvas != null) canvas.Dispose();\n                bodyScaled = Scale(bodySource, width, height);\n                headScaled = Scale(headSource, width, height);\n                canvas = new Bitmap(width, height, PixelFormat.Format32bppArgb);\n                drawnKey = \"\";\n            }\n            Draw(brain.Latest());\n        }\n\n        public void SetMood(Mood mood) { brain.SetMood(mood); }\n\n        public int TypedLength { set { brain.TypedLength = value; } }\n\n        /// <summary>A wink to say hello, then it starts watching.</summary>\n        public void Start()\n        {\n            brain.Play(Expression.Wink, 26, Expression.Neutral, 0);\n            timer.Start();\n        }\n\n        void Tick()\n        {\n            ticks++;\n            if (canvas == null) return;\n            float dpi = Dpi.Factor;\n            Point eye = new Point(centerX, bottomY - height + (int)(height * Face.EyeY));\n            Point cursor = Cursor.Position;\n            bool moved = Math.Abs(cursor.X - lastCursor.X) + Math.Abs(cursor.Y - lastCursor.Y) > 6 * dpi;\n            if (moved) lastCursor = cursor;\n            double lookX = Math.Max(-1, Math.Min(1, (cursor.X - eye.X) / (240.0 * dpi)));\n            double lookY = Math.Max(-1, Math.Min(1, (cursor.Y - eye.Y) / (170.0 * dpi)));\n            MascotPose pose = brain.Step(lookX, lookY, moved);\n            double sway = (Math.Sin(ticks * Math.PI * 2 / 60.0) * 0.5 + 0.5) * 3;\n            int bob = (int)Math.Round((sway + brain.HopOffset()) * dpi);\n            string key = pose.Key() + \"|\" + bob;\n            if (key == drawnKey) return;\n            drawnKey = key;\n            bobPixels = bob;\n            Draw(pose);\n        }\n\n        // ---- drawing -------------------------------------------------------------------------\n\n        void Draw(MascotPose pose)\n        {\n            if (canvas == null || !IsHandleCreated) return;\n            using (var g = Graphics.FromImage(canvas))\n            {\n                g.Clear(Color.Transparent);\n                g.SmoothingMode = SmoothingMode.AntiAlias;\n                g.InterpolationMode = InterpolationMode.HighQualityBilinear;\n                g.DrawImageUnscaled(bodyScaled, 0, 0);\n                // the head turns about the neck\n                float px = (float)(Face.PivotX * width), py = (float)(Face.PivotY * height);\n                g.TranslateTransform(px + (float)(pose.HeadX * width), py + (float)(pose.HeadY * height));\n                g.RotateTransform((float)pose.HeadTilt);\n                g.TranslateTransform(-px, -py);\n                g.DrawImageUnscaled(headScaled, 0, 0);\n                DrawFace(g, pose);\n            }\n            Push();\n        }\n\n        static Color Shade(Color c, double alpha)\n        {\n            return Color.FromArgb((int)Math.Max(0, Math.Min(255, alpha * 255)), c.R, c.G, c.B);\n        }\n\n        /// <summary>Quadratic curve as the cubic GDI+ wants.</summary>\n        static void Quad(GraphicsPath path, PointF a, PointF c, PointF b)\n        {\n            var c1 = new PointF(a.X + 2f / 3f * (c.X - a.X), a.Y + 2f / 3f * (c.Y - a.Y));\n            var c2 = new PointF(b.X + 2f / 3f * (c.X - b.X), b.Y + 2f / 3f * (c.Y - b.Y));\n            path.AddBezier(a, c1, c2, b);\n        }\n\n        static GraphicsPath RoundedBox(RectangleF r, float below, float above)\n        {\n            var path = new GraphicsPath();\n            float bd = Math.Max(0.5f, below * 2), td = Math.Max(0.5f, above * 2);\n            path.AddArc(r.Left, r.Top, td, td, 180, 90);\n            path.AddArc(r.Right - td, r.Top, td, td, 270, 90);\n            path.AddArc(r.Right - bd, r.Bottom - bd, bd, bd, 0, 90);\n            path.AddArc(r.Left, r.Bottom - bd, bd, bd, 90, 90);\n            path.CloseFigure();\n            return path;\n        }\n\n        /// <summary>The eyes and mouth, in the head's own (turned) coordinates, clipped to its dark screen.</summary>\n        void DrawFace(Graphics g, MascotPose pose)\n        {\n            float W = width, H = height;\n            FaceSpec spec = pose.Spec;\n            var screen = new RectangleF((float)Face.VisorX0 * W, (float)Face.VisorY0 * H, (float)(Face.VisorX1 - Face.VisorX0) * W, (float)(Face.VisorY1 - Face.VisorY0) * H);\n            screen.Inflate(-0.01f * W, -0.008f * H);\n            using (var clip = RoundedBox(screen, 0.045f * W, 0.045f * W))\n            {\n                g.SetClip(clip, CombineMode.Intersect);\n            }\n            float ew = (float)Face.EyeW * W, eh = (float)Face.EyeH * H;\n            float lw = ew * 0.4f;\n            float shiftX = (float)(pose.GazeX * Face.GazeShiftX) * W, shiftY = (float)(pose.GazeY * Face.GazeShiftY) * H;\n            var left = new PointF((float)Face.EyeLeftX * W + shiftX, (float)Face.EyeY * H + shiftY);\n            var right = new PointF((float)Face.EyeRightX * W + shiftX, (float)Face.EyeY * H + shiftY);\n            var mouth = new PointF((float)Face.MouthX * W + shiftX * 0.8f, (float)Face.MouthY * H + shiftY * 0.8f);\n            Color cyan = spec.Warning ? Color.FromArgb(255, 120, 120) : Color.FromArgb(102, 247, 252);\n\n            DrawEye(g, spec.Left, left, 1, 1, spec, pose, ew, eh, lw, cyan);\n            DrawEye(g, spec.Right, right, -1, spec.RightScale, spec, pose, ew, eh, lw, cyan);\n            DrawMouth(g, mouth, spec, W, ew, cyan, pose.Fade);\n            if (spec.Zzz) DrawZs(g, pose, W, H, cyan);\n            g.ResetClip();\n        }\n\n        /// <summary>Strokes or fills a shape with a soft glow around it (a few wider, fainter passes underneath).</summary>\n        static void Glow(Graphics g, GraphicsPath path, bool fill, Color color, float lineWidth, double fade)\n        {\n            for (int i = 3; i >= 1; i--)\n            {\n                using (var pen = new Pen(Shade(color, 0.16 * fade), lineWidth + i * lineWidth * 0.9f))\n                {\n                    pen.StartCap = LineCap.Round;\n                    pen.EndCap = LineCap.Round;\n                    pen.LineJoin = LineJoin.Round;\n                    g.DrawPath(pen, path);\n                }\n            }\n            if (fill)\n            {\n                using (var brush = new SolidBrush(Shade(color, fade))) g.FillPath(brush, path);\n            }\n            else\n            {\n                using (var pen = new Pen(Shade(color, fade), lineWidth))\n                {\n                    pen.StartCap = LineCap.Round;\n                    pen.EndCap = LineCap.Round;\n                    pen.LineJoin = LineJoin.Round;\n                    g.DrawPath(pen, path);\n                }\n            }\n        }\n\n        void DrawEye(Graphics g, EyeShape shape, PointF c, float side, double scale, FaceSpec spec, MascotPose pose, float ew, float eh, float lw, Color color)\n        {\n            float w = (float)(ew * spec.EyeWidth * scale), h = (float)(eh * spec.EyeHeight * scale);\n            var state = g.Save();\n            g.TranslateTransform(c.X, c.Y);\n            using (var path = new GraphicsPath())\n            {\n                bool fill = false;\n                switch (shape)\n                {\n                    case EyeShape.Open:\n                        {\n                            float full = Math.Max(lw * 0.7f, h * (float)pose.Openness);\n                            float shown = Math.Max(lw * 0.7f, full * (float)(1 - spec.Lid));\n                            g.RotateTransform(side * (float)spec.Tilt * -1f);\n                            float rb = Math.Min(w, shown) * 0.42f;\n                            float rt = spec.Lid > 0 ? Math.Min(w, shown) * 0.12f : rb;\n                            using (var box = RoundedBox(new RectangleF(-w / 2, -shown / 2 + (full - shown) / 2, w, shown), rb, rt)) path.AddPath(box, false);\n                            fill = true;\n                            break;\n                        }\n                    case EyeShape.ArcUp:\n                        Quad(path, new PointF(-w * 0.95f, h * 0.2f), new PointF(0, -h * 0.62f), new PointF(w * 0.95f, h * 0.2f));\n                        break;\n                    case EyeShape.ArcDown:\n                        Quad(path, new PointF(-w * 0.95f, -h * 0.12f), new PointF(0, h * 0.5f), new PointF(w * 0.95f, -h * 0.12f));\n                        break;\n                    case EyeShape.ChevronRight:\n                        path.AddLines(new PointF[] { new PointF(-w * 0.7f, -h * 0.42f), new PointF(w * 0.7f, 0), new PointF(-w * 0.7f, h * 0.42f) });\n                        break;\n                    case EyeShape.ChevronLeft:\n                        path.AddLines(new PointF[] { new PointF(w * 0.7f, -h * 0.42f), new PointF(-w * 0.7f, 0), new PointF(w * 0.7f, h * 0.42f) });\n                        break;\n                    case EyeShape.Underscore:\n                        if (pose.CursorOn) path.AddLine(-w * 0.85f, h * 0.4f, w * 0.85f, h * 0.4f);\n                        break;\n                    case EyeShape.Cross:\n                        path.AddLine(-w * 0.7f, -h * 0.32f, w * 0.7f, h * 0.32f);\n                        path.StartFigure();\n                        path.AddLine(-w * 0.7f, h * 0.32f, w * 0.7f, -h * 0.32f);\n                        break;\n                }\n                if (path.PointCount > 0) Glow(g, path, fill, color, lw, pose.Fade);\n            }\n            g.Restore(state);\n        }\n\n        void DrawMouth(Graphics g, PointF m, FaceSpec spec, float W, float ew, Color color, double fade)\n        {\n            float mw = 0.056f * W * (float)spec.MouthSize;\n            float k = (float)spec.Curve;\n            var state = g.Save();\n            g.TranslateTransform(m.X, m.Y);\n            using (var path = new GraphicsPath())\n            {\n                bool fill = false;\n                switch (spec.Mouth)\n                {\n                    case MouthShape.Smile:\n                        Quad(path, new PointF(-mw, 0), new PointF(0, k * mw * 1.6f), new PointF(mw, 0));\n                        break;\n                    case MouthShape.Grin:\n                        path.AddLine(-mw, -mw * 0.15f, mw, -mw * 0.15f);\n                        path.AddArc(-mw, -mw * 0.15f - mw, mw * 2, mw * 2, 0, 180);\n                        path.CloseFigure();\n                        fill = true;\n                        break;\n                    case MouthShape.O:\n                        {\n                            float r = mw * 0.42f;\n                            path.AddEllipse(-r, -r * 1.2f, r * 2, r * 2.4f);\n                            break;\n                        }\n                    case MouthShape.Flat:\n                        path.AddLine(-mw * 0.55f, 0, mw * 0.55f, 0);\n                        break;\n                    case MouthShape.Wave:\n                        {\n                            var points = new PointF[25];\n                            for (int i = 0; i <= 24; i++)\n                            {\n                                float t = i / 24f;\n                                points[i] = new PointF((t - 0.5f) * mw * 1.8f, (float)Math.Sin(t * Math.PI * 3) * mw * 0.18f);\n                            }\n                            path.AddLines(points);\n                            break;\n                        }\n                    case MouthShape.Smirk:\n                        Quad(path, new PointF(-mw * 0.9f, mw * 0.1f), new PointF(mw * 0.1f, k * mw * 1.5f), new PointF(mw, -mw * 0.45f));\n                        break;\n                }\n                Glow(g, path, fill, color, ew * 0.3f, fade);\n            }\n            g.Restore(state);\n        }\n\n        static void DrawZs(Graphics g, MascotPose pose, float W, float H, Color color)\n        {\n            var baseAt = new PointF(0.6f * W, 0.27f * H);\n            for (int i = 0; i < 3; i++)\n            {\n                double t = (pose.ZPhase + i / 3.0) % 1.0;\n                float size = (float)(0.012 + 0.012 * t) * W;\n                double alpha = pose.Fade * Math.Sin(t * Math.PI);\n                using (var pen = new Pen(Shade(color, alpha), Math.Max(1f, size * 0.28f)))\n                {\n                    pen.StartCap = LineCap.Round;\n                    pen.EndCap = LineCap.Round;\n                    pen.LineJoin = LineJoin.Round;\n                    float x = baseAt.X + (float)t * 0.04f * W, y = baseAt.Y - (float)t * 0.07f * H;\n                    g.DrawLines(pen, new PointF[] { new PointF(x - size, y - size), new PointF(x + size, y - size), new PointF(x - size, y + size), new PointF(x + size, y + size) });\n                }\n            }\n        }\n\n        /// <summary>Hands the picture to the system as the window's whole appearance, with its own transparency.</summary>\n        void Push()\n        {\n            IntPtr screenDc = Native.GetDC(IntPtr.Zero);\n            IntPtr memoryDc = Native.CreateCompatibleDC(screenDc);\n            IntPtr bitmap = IntPtr.Zero;\n            IntPtr previous = IntPtr.Zero;\n            try\n            {\n                bitmap = canvas.GetHbitmap(Color.FromArgb(0));\n                previous = Native.SelectObject(memoryDc, bitmap);\n                var size = new Native.SIZE();\n                size.cx = width;\n                size.cy = height;\n                var source = new Native.POINT();\n                var destination = new Native.POINT();\n                destination.X = centerX - width / 2;\n                destination.Y = bottomY - height - bobPixels;\n                var blend = new Native.BLENDFUNCTION();\n                blend.BlendOp = 0;          // AC_SRC_OVER\n                blend.BlendFlags = 0;\n                blend.SourceConstantAlpha = 255;\n                blend.AlphaFormat = 1;      // AC_SRC_ALPHA: use the picture's own transparency\n                Native.UpdateLayeredWindow(Handle, screenDc, ref destination, ref size, memoryDc, ref source, 0, ref blend, 2);\n            }\n            catch (Exception)\n            {\n                // a drawing hiccup: the next tick tries again\n            }\n            finally\n            {\n                if (bitmap != IntPtr.Zero)\n                {\n                    Native.SelectObject(memoryDc, previous);\n                    Native.DeleteObject(bitmap);\n                }\n                Native.DeleteDC(memoryDc);\n                Native.ReleaseDC(IntPtr.Zero, screenDc);\n            }\n        }\n\n        protected override void Dispose(bool disposing)\n        {\n            if (disposing) timer.Dispose();\n            base.Dispose(disposing);\n        }\n    }\n\n    /// <summary>The window: a prompt box that becomes a progress feed once a request is sent.</summary>\n    sealed class PromptForm : Form\n    {\n        readonly HudArgs args;\n        readonly HudState state = new HudState();\n        string modelKey;\n\n        readonly Label dot = new Label();\n        readonly Label appName = new Label();\n        readonly Label statusLabel = new Label();\n        readonly Label spinner = new Label();\n        readonly PillButton closeButton = new PillButton(\"\\u2715\", Theme.Secondary, Theme.ButtonFill);\n        readonly PillButton stopButton = new PillButton(\"Stop\", Theme.Danger, Color.FromArgb(48, 20, 20));\n        readonly PillButton copyButton = new PillButton(\"Copy\", Theme.Text, Theme.ButtonFill);\n        readonly PillButton modelButton = new PillButton(\"\", Theme.Secondary, Theme.ButtonFill);\n        readonly TextBox input = new TextBox();\n        readonly RoundButton sendButton = new RoundButton(RoundButton.Glyphs.Arrow);\n        readonly RoundButton modelGlyph = new RoundButton(RoundButton.Glyphs.Sparkle);\n        MascotForm mascot;\n        Rectangle pillRect;\n        readonly RoundPanel inputBox = new RoundPanel();\n        readonly Panel divider = new Panel();\n        readonly RichTextBox feed = new RichTextBox();\n        readonly System.Windows.Forms.Timer spin = new System.Windows.Forms.Timer();\n        readonly System.Windows.Forms.Timer copyReset = new System.Windows.Forms.Timer();\n        readonly ContextMenuStrip modelMenu = new ContextMenuStrip();\n        readonly ToolTip tips = new ToolTip();\n        int spinFrame;\n        int answerStart = -1;\n        bool closing;\n        const string SpinFrames = \"\\u25D0\\u25D3\\u25D1\\u25D2\";\n        readonly Font fontSmall = new Font(\"Segoe UI Semibold\", 8f);\n        readonly Font fontNormal = new Font(\"Segoe UI\", 10f);\n        readonly Font fontMedium = new Font(\"Segoe UI Semibold\", 11f);\n        readonly Font fontAnswer = new Font(\"Segoe UI\", 10.5f);\n\n        public PromptForm(HudArgs args)\n        {\n            this.args = args;\n            modelKey = args.ModelKey;\n            SuspendLayout();\n            Text = \"Remote Hands\";\n            FormBorderStyle = FormBorderStyle.None;\n            ShowInTaskbar = false;\n            TopMost = true;\n            StartPosition = FormStartPosition.Manual;\n            BackColor = Theme.Background;\n            ForeColor = Theme.Text;\n            KeyPreview = true;\n            DoubleBuffered = true;\n            AutoScaleMode = AutoScaleMode.None;\n\n            dot.Text = \"\\u25CF\";\n            dot.ForeColor = Theme.Accent;\n            dot.Font = new Font(\"Segoe UI\", 7f);\n            dot.AutoSize = true;\n            appName.Text = args.App;\n            appName.ForeColor = Theme.Secondary;\n            appName.Font = new Font(\"Segoe UI Semibold\", 9.5f);\n            appName.AutoSize = true;\n            statusLabel.ForeColor = Theme.Accent;\n            statusLabel.Font = new Font(\"Segoe UI Semibold\", 9.5f);\n            statusLabel.AutoSize = true;\n            statusLabel.Visible = false;\n            spinner.ForeColor = Theme.Accent;\n            spinner.Font = new Font(\"Segoe UI Symbol\", 10f);\n            spinner.AutoSize = true;\n            spinner.Visible = false;\n\n            input.BorderStyle = BorderStyle.None;\n            input.Multiline = true;      // the pill grows with the text; Enter sends, Shift+Enter starts a new line\n            input.WordWrap = true;\n            input.ScrollBars = ScrollBars.None;\n            input.BackColor = Theme.Background;\n            input.ForeColor = Theme.Text;\n            input.Font = new Font(\"Segoe UI\", 15f);\n\n            divider.BackColor = Theme.Divider;\n            divider.Visible = false;\n\n            feed.ReadOnly = true;\n            feed.BorderStyle = BorderStyle.None;\n            feed.BackColor = Theme.Background;\n            feed.ForeColor = Theme.Text;\n            feed.Font = new Font(\"Segoe UI\", 10.5f);\n            feed.DetectUrls = true;\n            feed.TabStop = false;\n            feed.Visible = false;\n            feed.ScrollBars = RichTextBoxScrollBars.Vertical;\n            feed.LinkClicked += OnLinkClicked;\n            feed.Cursor = Cursors.IBeam;\n\n            inputBox.Visible = false;\n\n            closeButton.Click += delegate { Cancel(); };\n            stopButton.Click += delegate { Stop(); };\n            stopButton.Visible = false;\n            copyButton.Click += delegate { CopyAnswer(); };\n            copyButton.Visible = false;\n            modelButton.Click += OnModelClicked;\n            modelButton.Visible = false;   // the progress card's label button; the prompt has the round one beside the pill\n            modelGlyph.Outlined = true;\n            modelGlyph.Visible = args.Models.Count > 0;\n            modelGlyph.Click += OnModelClicked;\n            modelButton.TextAlign = ContentAlignment.MiddleCenter;\n            UpdateModelButton();\n\n            spin.Interval = 110;\n            spin.Tick += delegate\n            {\n                spinFrame = (spinFrame + 1) % SpinFrames.Length;\n                spinner.Text = SpinFrames[spinFrame].ToString();\n            };\n            copyReset.Interval = 1600;\n            copyReset.Tick += delegate\n            {\n                copyReset.Stop();\n                copyButton.Text = \"Copy\";\n                copyButton.ForeColor = Theme.Text;\n            };\n\n            Controls.Add(dot);\n            Controls.Add(appName);\n            Controls.Add(statusLabel);\n            Controls.Add(spinner);\n            Controls.Add(closeButton);\n            Controls.Add(stopButton);\n            Controls.Add(copyButton);\n            Controls.Add(divider);\n            Controls.Add(feed);\n            Controls.Add(inputBox);\n            Controls.Add(modelButton);\n            Controls.Add(sendButton);\n            Controls.Add(modelGlyph);\n            Controls.Add(input);\n\n            // Every part of the window except the controls drags it.\n            MouseDown += DragWindow;\n            dot.MouseDown += DragWindow;\n            appName.MouseDown += DragWindow;\n            statusLabel.MouseDown += DragWindow;\n\n            input.KeyDown += OnInputKeyDown;\n            input.TextChanged += OnInputChanged;\n            sendButton.Click += delegate { Submit(); input.Focus(); };\n            LocationChanged += delegate { PlaceMascot(); };\n            Layout_Collapsed();\n            ResumeLayout(false);\n        }\n\n        // ---- layout ------------------------------------------------------------------------\n\n        Rectangle WorkArea()\n        {\n            return Screen.FromPoint(Cursor.Position).WorkingArea;\n        }\n\n        void ApplyRegion()\n        {\n            if (Width <= 0 || Height <= 0) return;\n            Region = Region.FromHrgn(Native.CreateRoundRectRgn(0, 0, Width + 1, Height + 1, Dpi.S(36), Dpi.S(36)));\n        }\n\n        /// <summary>The small prompt: a chat pill that grows with the text, and a round model button beside it (the mascot stands on top).</summary>\n        void Layout_Collapsed()\n        {\n            bool hasModels = args.Models.Count > 0;\n            int w = Dpi.S(420) + (hasModels ? Dpi.S(8) + Dpi.S(52) : 0), h = Dpi.S(52);\n            Rectangle wa = WorkArea();\n            Bounds = new Rectangle(wa.Left + (wa.Width - w) / 2, wa.Top + Math.Max(Dpi.S(190), (int)(wa.Height * 0.34)), w, h);\n            BackColor = Theme.Pill;\n            input.BackColor = Theme.Pill;\n            input.Font = new Font(\"Segoe UI\", 11.25f);\n            closeButton.Visible = false;\n            dot.Visible = false;\n            appName.Visible = false;\n            modelButton.Visible = false;\n            sendButton.Visible = true;\n            modelGlyph.Visible = hasModels;\n            LayoutPill();\n        }\n\n        /// <summary>\n        /// The pill is the text plus 15 above and below it; the send arrow sits on its bottom line and the window grows\n        /// upward, so the mascot rides on top. Only the pill and the round button are part of the window: the gap\n        /// between them is see-through and click-through.\n        /// </summary>\n        void LayoutPill()\n        {\n            int pillW = Dpi.S(420), minH = Dpi.S(52), gap = Dpi.S(8), left = Dpi.S(22), right = Dpi.S(52);\n            bool hasModels = args.Models.Count > 0;\n            int lineH = TextRenderer.MeasureText(\"Ag\", input.Font).Height;\n            int measured = lineH;\n            if (input.Text.Length > 0)\n            {\n                measured = TextRenderer.MeasureText(input.Text + \"x\", input.Font, new Size(pillW - left - right - Dpi.S(8), 10000), TextFormatFlags.WordBreak | TextFormatFlags.NoPadding).Height;\n            }\n            int textH = Math.Min(lineH * 9 + Dpi.S(4), Math.Max(Dpi.S(22), measured + Dpi.S(4)));\n            int pillH = Math.Max(minH, textH + Dpi.S(30));\n            int w = pillW + (hasModels ? gap + minH : 0);\n            int bottom = Top + Height;\n            Bounds = new Rectangle(Left, bottom - pillH, w, pillH);\n            pillRect = new Rectangle(0, 0, pillW, pillH);\n            input.Bounds = new Rectangle(left, Dpi.S(15), pillW - left - right, textH);\n            sendButton.Bounds = new Rectangle(pillW - Dpi.S(10) - Dpi.S(32), pillH - Dpi.S(10) - Dpi.S(32), Dpi.S(32), Dpi.S(32));\n            modelGlyph.Bounds = new Rectangle(pillW + gap, pillH - minH, minH, minH);\n            using (var path = new GraphicsPath())\n            {\n                using (var pill = Shapes.Rounded(pillRect, Dpi.S(26))) path.AddPath(pill, false);\n                if (hasModels)\n                {\n                    using (var round = Shapes.Rounded(modelGlyph.Bounds, minH / 2)) path.AddPath(round, false);\n                }\n                Region = new Region(path);\n            }\n            PlaceMascot();\n            Invalidate();\n        }\n\n        void Layout_Expanded()\n        {\n            Rectangle wa = WorkArea();\n            BackColor = Theme.Background;\n            sendButton.Visible = false;\n            modelGlyph.Visible = false;\n            modelButton.Visible = args.Models.Count > 0;\n            dot.Visible = true;\n            appName.Visible = true;\n            closeButton.Visible = true;\n            int w = Dpi.S(640);\n            int h = Math.Min(Dpi.S(600), Math.Max(Dpi.S(420), wa.Height - Dpi.S(80)));\n            Bounds = new Rectangle(wa.Right - w - Dpi.S(24), wa.Top + Dpi.S(24), w, h);\n            ApplyRegion();\n            int mascotRoom = mascot != null ? Dpi.S(54) : 0; // the mascot stands in the header's corner\n            dot.Location = new Point(Dpi.S(22) + mascotRoom, Dpi.S(19));\n            appName.Location = new Point(Dpi.S(36) + mascotRoom, Dpi.S(15));\n            int statusX = appName.Right + Dpi.S(20);\n            spinner.Location = new Point(statusX, Dpi.S(14));\n            statusLabel.Location = new Point(statusX + Dpi.S(22), Dpi.S(15));\n            closeButton.Bounds = new Rectangle(w - Dpi.S(44), Dpi.S(12), Dpi.S(26), Dpi.S(24));\n            stopButton.Bounds = new Rectangle(w - Dpi.S(118), Dpi.S(12), Dpi.S(64), Dpi.S(24));\n            copyButton.Bounds = stopButton.Bounds;\n            divider.Bounds = new Rectangle(0, Dpi.S(52), w, 1);\n            int boxH = Dpi.S(44);\n            inputBox.Bounds = new Rectangle(Dpi.S(16), h - Dpi.S(16) - boxH, w - Dpi.S(32), boxH);\n            int feedTop = Dpi.S(60);\n            int feedBottom = h - Dpi.S(16) - boxH - Dpi.S(12);\n            feed.Bounds = new Rectangle(Dpi.S(22), feedTop, w - Dpi.S(44), feedBottom - feedTop);\n            int pill = modelButton.Visible ? Dpi.S(214) : 0;\n            input.Font = new Font(\"Segoe UI\", 11.5f);\n            input.BackColor = Theme.Field;\n            // the text box and model button sit inside the rounded input box\n            input.Bounds = new Rectangle(inputBox.Left + Dpi.S(16), inputBox.Top + Dpi.S(12), inputBox.Width - Dpi.S(32) - pill, Dpi.S(22));\n            modelButton.Bounds = new Rectangle(inputBox.Right - Dpi.S(10) - Dpi.S(206), inputBox.Top + Dpi.S(9), Dpi.S(206), Dpi.S(26));\n            inputBox.Visible = true;\n            divider.Visible = true;\n            feed.Visible = true;\n            statusLabel.Visible = true;\n            input.BringToFront();\n            modelButton.BringToFront();\n            closeButton.BringToFront();\n            stopButton.BringToFront();\n            copyButton.BringToFront();\n            Invalidate();\n        }\n\n        protected override void OnPaint(PaintEventArgs e)\n        {\n            base.OnPaint(e);\n            e.Graphics.SmoothingMode = SmoothingMode.AntiAlias;\n            if (!state.IsExpanded)\n            {\n                using (var pen = new Pen(Theme.PillBorder))\n                using (var pill = Shapes.Rounded(new Rectangle(0, 0, pillRect.Width - 1, pillRect.Height - 1), Dpi.S(26)))\n                {\n                    e.Graphics.DrawPath(pen, pill);\n                }\n                return;\n            }\n            using (var path = Shapes.Rounded(new Rectangle(0, 0, Width - 1, Height - 1), Dpi.S(18)))\n            using (var pen = new Pen(Theme.Border))\n            {\n                e.Graphics.DrawPath(pen, path);\n            }\n        }\n\n        protected override CreateParams CreateParams\n        {\n            get\n            {\n                var cp = base.CreateParams;\n                cp.ExStyle |= 0x80; // WS_EX_TOOLWINDOW: no taskbar button, no Alt+Tab entry\n                return cp;\n            }\n        }\n\n        void DragWindow(object sender, MouseEventArgs e)\n        {\n            if (e.Button != MouseButtons.Left) return;\n            Native.ReleaseCapture();\n            Native.SendMessage(Handle, Native.WM_NCLBUTTONDOWN, new IntPtr(Native.HTCAPTION), IntPtr.Zero);\n        }\n\n        // ---- start and focus ----------------------------------------------------------------\n\n        protected override void OnShown(EventArgs e)\n        {\n            base.OnShown(e);\n            Native.ForceForeground(Handle);\n            Activate();\n            SetPlaceholder(Copy.Placeholder);\n            input.Focus();\n            StartMascot();\n            // A one-shot prompt has no daemon to listen to: it prints the first request and ends.\n            if (!args.Once)\n            {\n                var reader = new Thread(ReadDaemon);\n                reader.IsBackground = true;\n                reader.Start();\n            }\n        }\n\n        void SetPlaceholder(string text)\n        {\n            try\n            {\n                Native.SendMessage(input.Handle, Native.EM_SETCUEBANNER, new IntPtr(1), text);\n            }\n            catch (Exception)\n            {\n                // no placeholder is not a problem\n            }\n        }\n\n        // ---- what the person does ------------------------------------------------------------\n\n        // ---- the mascot ----------------------------------------------------------------------\n\n        static string MascotDir()\n        {\n            string over = Environment.GetEnvironmentVariable(\"RH_MASCOT_DIR\");\n            if (!string.IsNullOrEmpty(over)) return over;\n            return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), \".remote-hands\", \"mascot\");\n        }\n\n        void StartMascot()\n        {\n            MascotForm made = new MascotForm(MascotDir());\n            if (!made.Available)\n            {\n                made.Dispose();\n                return;\n            }\n            made.CloseRequested = Cancel;\n            mascot = made;\n            made.Show(this);\n            PlaceMascot();\n            made.Start();\n        }\n\n        /// <summary>On top of the prompt while it is small, in the header's corner once it is the progress card.</summary>\n        void PlaceMascot()\n        {\n            if (mascot == null) return;\n            if (state.IsExpanded)\n            {\n                int h = Dpi.S(50);\n                int w = (int)Math.Round(h * mascot.Aspect);\n                mascot.Stand(Left + Dpi.S(14) + w / 2, Top + Dpi.S(6) + h, h);\n            }\n            else\n            {\n                mascot.Stand(Left + Width / 2, Top - Dpi.S(4), Dpi.S(140));\n            }\n        }\n\n        void OnInputChanged(object sender, EventArgs e)\n        {\n            if (!state.IsExpanded) LayoutPill();\n            sendButton.Ready = input.Text.Trim().Length > 0;\n            if (mascot != null && !state.IsExpanded)\n            {\n                mascot.TypedLength = input.Text.Length;\n                mascot.SetMood(input.Text.Length == 0 ? Mood.Idle : Mood.Typing);\n            }\n        }\n\n        void OnInputKeyDown(object sender, KeyEventArgs e)\n        {\n            if (e.KeyCode == Keys.Enter && !e.Shift)\n            {\n                e.SuppressKeyPress = true;\n                e.Handled = true;\n                Submit();\n            }\n        }\n\n        protected override bool ProcessCmdKey(ref Message msg, Keys keyData)\n        {\n            if (keyData == Keys.Escape)\n            {\n                if (state.IsExpanded && state.IsWorking) Stop();\n                else Cancel();\n                return true;\n            }\n            if (keyData == (Keys.Control | Keys.OemPeriod))\n            {\n                Stop();\n                return true;\n            }\n            return base.ProcessCmdKey(ref msg, keyData);\n        }\n\n        void Submit()\n        {\n            string text = input.Text.Trim();\n            if (text.Length == 0) return;\n            input.Text = \"\";\n            Wire.Send(Messages.Submit(text, args.App, args.WindowTitle, args.Models.Count > 0 ? modelKey : \"\"));\n            if (args.Once)\n            {\n                Thread.Sleep(50);\n                Environment.Exit(0);\n            }\n            bool first = !state.IsExpanded;\n            state.Submitted();\n            if (first) TransitionToProgress();\n            AppendEntry(EntryKind.Goal, text);\n            ApplyChrome();\n            SetPlaceholder(\"Type a follow-up, or press Esc to stop\");\n        }\n\n        void TransitionToProgress()\n        {\n            SuspendLayout();\n            Layout_Expanded();\n            appName.Text = args.App;\n            ResumeLayout(true);\n            PlaceMascot();\n            input.Focus();\n        }\n\n        void Stop()\n        {\n            if (!state.IsExpanded || !state.IsWorking) return;\n            Wire.Send(Messages.Stop());\n            AppendEntry(state.StopClicked().Kind, \"Stopped.\");\n            ApplyChrome();\n            input.Focus();\n        }\n\n        void Cancel()\n        {\n            if (closing) return;\n            closing = true;\n            Wire.Send(Messages.Cancel());\n            Thread.Sleep(50);\n            Environment.Exit(0);\n        }\n\n        void CopyAnswer()\n        {\n            if (state.AnswerText.Length == 0) return;\n            try\n            {\n                Clipboard.SetText(state.AnswerText);\n                copyButton.Text = \"Copied\";\n                copyButton.ForeColor = Theme.Success;\n                copyReset.Stop();\n                copyReset.Start();\n            }\n            catch (Exception)\n            {\n                // another program is holding the clipboard: the button stays \"Copy\" and the person can try again\n            }\n        }\n\n        void OnLinkClicked(object sender, LinkClickedEventArgs e)\n        {\n            // Only web and mail links open: a file path or a program in the agent's text never does.\n            if (!Links.IsOpenable(e.LinkText)) return;\n            try\n            {\n                Process.Start(new ProcessStartInfo(e.LinkText.Trim()) { UseShellExecute = true });\n            }\n            catch (Exception)\n            {\n                // no program for that kind of link\n            }\n        }\n\n        // ---- model choice --------------------------------------------------------------------\n\n        void UpdateModelButton()\n        {\n            string label = \"\";\n            foreach (ModelOption m in args.Models)\n            {\n                if (m.Key == modelKey) label = m.Label;\n            }\n            if (label.Length == 0 && args.Models.Count > 0) label = args.Models[0].Label;\n            modelButton.Text = label + \"  \\u25BE\";\n            tips.SetToolTip(modelGlyph, \"Model: \" + label);\n        }\n\n        void OnModelClicked(object sender, EventArgs e)\n        {\n            modelMenu.Items.Clear();\n            modelMenu.BackColor = Theme.Field;\n            modelMenu.ForeColor = Theme.Text;\n            modelMenu.ShowCheckMargin = true;\n            foreach (ModelOption m in args.Models)\n            {\n                var item = new ToolStripMenuItem(m.Label);\n                item.Tag = m.Key;\n                item.Checked = m.Key == modelKey;\n                item.BackColor = Theme.Field;\n                item.ForeColor = Theme.Text;\n                item.Click += OnModelPicked;\n                modelMenu.Items.Add(item);\n            }\n            Control anchor = state.IsExpanded ? (Control)modelButton : modelGlyph;\n            modelMenu.Show(anchor, new Point(0, anchor.Height));\n        }\n\n        void OnModelPicked(object sender, EventArgs e)\n        {\n            var item = sender as ToolStripMenuItem;\n            if (item == null) return;\n            string key = item.Tag as string;\n            if (key == null || key == modelKey) return;\n            modelKey = key;\n            UpdateModelButton();\n            Wire.Send(Messages.Model(key));\n            input.Focus();\n        }\n\n        // ---- the daemon's messages -----------------------------------------------------------\n\n        void ReadDaemon()\n        {\n            try\n            {\n                StreamReader reader = Wire.Input();\n                string line;\n                while ((line = reader.ReadLine()) != null)\n                {\n                    string copy = line;\n                    try\n                    {\n                        BeginInvoke(new Action(delegate { HandleLine(copy); }));\n                    }\n                    catch (Exception)\n                    {\n                        return; // the window is gone\n                    }\n                }\n            }\n            catch (Exception)\n            {\n                // input broke: same as the daemon going away\n            }\n            // The daemon ended: nothing is left to talk to, so the window goes too.\n            Environment.Exit(0);\n        }\n\n        void HandleLine(string line)\n        {\n            string trimmed = line.Trim();\n            if (trimmed.Length == 0) return;\n            var message = Json.Parse(trimmed) as Dictionary<string, object>;\n            if (message == null) return;\n            if (Json.GetString(message, \"event\") == \"context\") return; // browser tabs and files to attach: not on Windows yet\n            UpdateResult result = state.Apply(Json.GetString(message, \"status\"), Json.GetString(message, \"text\"), Json.GetString(message, \"role\"));\n            if (result.Ignored) return;\n            foreach (FeedEntry entry in result.Entries) AppendEntry(entry.Kind, entry.Text);\n            ApplyChrome();\n            if (result.GiveInputBack) input.Focus();\n        }\n\n        void ApplyChrome()\n        {\n            if (!state.IsExpanded) return;\n            if (mascot != null) mascot.SetMood(MascotBrain.MoodFor(state.IsWorking, state.StatusTone));\n            statusLabel.Text = state.StatusWord;\n            statusLabel.ForeColor = Theme.ForTone(state.StatusTone);\n            spinner.Visible = state.IsWorking;\n            if (state.IsWorking) { if (!spin.Enabled) spin.Start(); } else spin.Stop();\n            stopButton.Visible = state.StopVisible;\n            copyButton.Visible = state.CopyVisible;\n            if (state.CopyVisible)\n            {\n                copyReset.Stop();\n                copyButton.Text = \"Copy\";\n                copyButton.ForeColor = Theme.Text;\n            }\n            SetPlaceholder(state.IsWorking ? \"Type a follow-up, or press Esc to stop\" : \"Ask a follow-up, or press Esc to close\");\n        }\n\n        // ---- the feed ------------------------------------------------------------------------\n\n        void Append(string text, Color color, Font font)\n        {\n            feed.SelectionStart = feed.TextLength;\n            feed.SelectionLength = 0;\n            feed.SelectionColor = color;\n            feed.SelectionFont = font;\n            feed.AppendText(text);\n        }\n\n        void AppendEntry(EntryKind kind, string rawText)\n        {\n            string text = rawText == null ? \"\" : rawText.Trim();\n            if (text.Length == 0) return;\n            bool first = feed.TextLength == 0;\n            Font small = fontSmall;\n            Font normal = fontNormal;\n            Font medium = fontMedium;\n            Font answerFont = fontAnswer;\n            int start = feed.TextLength;\n            switch (kind)\n            {\n                case EntryKind.Goal:\n                    Append((first ? \"\" : \"\\n\") + \"YOU\\n\", Theme.Tertiary, small);\n                    Append(text + \"\\n\", Theme.Text, medium);\n                    break;\n                case EntryKind.Step:\n                    Append(\"\\u2713  \", Theme.Success, normal);\n                    Append(text + \"\\n\", Theme.Secondary, normal);\n                    break;\n                case EntryKind.Note:\n                    Append(\"\\u00B7  \", Theme.Tertiary, normal);\n                    Append(text + \"\\n\", Theme.Tertiary, normal);\n                    break;\n                case EntryKind.Attention:\n                    Append(\"!  \", Theme.Warning, medium);\n                    Append(text + \"\\n\", Theme.Warning, normal);\n                    break;\n                case EntryKind.Error:\n                    Append(\"\\u2715  \", Theme.Danger, medium);\n                    Append(text + \"\\n\", Theme.Danger, normal);\n                    break;\n                default:\n                    Append((first ? \"\" : \"\\n\") + \"RESULT\\n\", Theme.Success, small);\n                    answerStart = feed.TextLength;\n                    Append(text + \"\\n\", Theme.Text, answerFont);\n                    break;\n            }\n            if (kind == EntryKind.Answer)\n            {\n                // a long answer is read from its first line\n                feed.SelectionStart = feed.TextLength;\n                feed.ScrollToCaret();\n                feed.SelectionStart = Math.Max(0, answerStart);\n                feed.ScrollToCaret();\n            }\n            else\n            {\n                feed.SelectionStart = feed.TextLength;\n                feed.ScrollToCaret();\n            }\n            feed.SelectionLength = 0;\n        }\n    }\n\n    /// <summary>Waits for the hotkey and says which program was in front.</summary>\n    sealed class HotkeyWindow : NativeWindow\n    {\n        DateTime last = DateTime.MinValue;\n        string keys = \"\";\n\n        public bool Register()\n        {\n            var cp = new CreateParams();\n            cp.Parent = Native.HWND_MESSAGE;\n            CreateHandle(cp);\n            if (Native.RegisterHotKey(Handle, 1, Native.MOD_CONTROL | Native.MOD_SHIFT | Native.MOD_NOREPEAT, Native.VK_SPACE))\n            {\n                keys = \"Ctrl+Shift+Space\";\n                return true;\n            }\n            // another program holds the first choice: take the next one rather than do nothing\n            if (Native.RegisterHotKey(Handle, 2, Native.MOD_CONTROL | Native.MOD_ALT | Native.MOD_NOREPEAT, Native.VK_SPACE))\n            {\n                keys = \"Ctrl+Alt+Space\";\n                return true;\n            }\n            return false;\n        }\n\n        public string Keys { get { return keys; } }\n\n        protected override void WndProc(ref Message m)\n        {\n            if (m.Msg == Native.WM_HOTKEY) OnHotkey();\n            base.WndProc(ref m);\n        }\n\n        void OnHotkey()\n        {\n            if ((DateTime.UtcNow - last).TotalMilliseconds < 500) return;\n            last = DateTime.UtcNow;\n            // This program just received the keypress, so Windows lets it hand the keyboard to the prompt window that follows.\n            try\n            {\n                Native.AllowSetForegroundWindow(-1);\n            }\n            catch (Exception)\n            {\n                // the prompt asks for the keyboard itself, with the Alt-tap fallback\n            }\n            string app = \"Desktop\";\n            string title = \"\";\n            try\n            {\n                IntPtr fg = Native.GetForegroundWindow();\n                uint pid;\n                Native.GetWindowThreadProcessId(fg, out pid);\n                if (pid != 0 && pid != (uint)Process.GetCurrentProcess().Id)\n                {\n                    using (Process p = Process.GetProcessById((int)pid))\n                    {\n                        app = AppNames.Friendly(p.ProcessName);\n                    }\n                    var sb = new StringBuilder(512);\n                    Native.GetWindowText(fg, sb, sb.Capacity);\n                    title = sb.ToString();\n                }\n            }\n            catch (Exception)\n            {\n                // a program that cannot be inspected is just \"Desktop\"\n            }\n            Wire.Send(Messages.Hotkey(app, title));\n        }\n    }\n\n    /// <summary>Starts at login, runs the daemon's listener with no console window, and starts it again if it stops.</summary>\n    static class Supervisor\n    {\n        static string HomeDir()\n        {\n            return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile), \".remote-hands\");\n        }\n\n        static string LogLine(string text)\n        {\n            return DateTime.Now.ToString(\"yyyy-MM-dd HH:mm:ss\") + \" \" + text;\n        }\n\n        static void Log(string text)\n        {\n            try\n            {\n                string dir = Path.Combine(HomeDir(), \"logs\");\n                Directory.CreateDirectory(dir);\n                string file = Path.Combine(dir, \"hud.log\");\n                lock (typeof(Supervisor))\n                {\n                    // the log never grows without end: start over once it is large\n                    if (File.Exists(file) && new FileInfo(file).Length > 1000000) File.Delete(file);\n                    File.AppendAllText(file, LogLine(text) + \"\\n\", new UTF8Encoding(false));\n                }\n            }\n            catch (Exception)\n            {\n                // logging must never stop the HUD\n            }\n        }\n\n        /// <summary>What the listener said about its shortcut belongs to that listener: when it ends, \"ready\" is no longer true.</summary>\n        static void ForgetReadyStatus()\n        {\n            try\n            {\n                string file = Path.Combine(HomeDir(), \"hud-status.json\");\n                if (File.Exists(file) && File.ReadAllText(file, new UTF8Encoding(false)).IndexOf(\"\\\"ready\\\"\", StringComparison.Ordinal) >= 0) File.Delete(file);\n            }\n            catch (Exception)\n            {\n                // the next listener overwrites it\n            }\n        }\n\n        static SupervisorSettings ReadSettings(HudArgs args)\n        {\n            var settings = new SupervisorSettings();\n            try\n            {\n                string file = Path.Combine(HomeDir(), \"hud.json\");\n                if (File.Exists(file)) settings = SupervisorSettings.Parse(File.ReadAllText(file, new UTF8Encoding(false)));\n            }\n            catch (Exception)\n            {\n                // unreadable settings: the arguments (if any) decide\n            }\n            if (args.NodePath.Length > 0) settings.Node = args.NodePath;\n            if (args.CliPath.Length > 0) settings.Cli = args.CliPath;\n            return settings;\n        }\n\n        public static int Run(HudArgs args)\n        {\n            bool created;\n            using (var mutex = new Mutex(true, \"Local\\\\RemoteHandsHudSupervisor\", out created))\n            {\n                if (!created) return 0; // already running\n                try\n                {\n                    Directory.CreateDirectory(HomeDir());\n                    File.WriteAllText(Path.Combine(HomeDir(), \"hud-supervisor.pid\"), Process.GetCurrentProcess().Id.ToString(), new UTF8Encoding(false));\n                }\n                catch (Exception)\n                {\n                    // `rh hud uninstall` then falls back to the registry entry only\n                }\n                int wait = 1000;\n                while (true)\n                {\n                    DateTime started = DateTime.UtcNow;\n                    SupervisorSettings settings = ReadSettings(args);\n                    if (settings.Node.Length == 0 || settings.Cli.Length == 0)\n                    {\n                        Log(\"supervisor: no Node or CLI path is set (run: rh hud install)\");\n                    }\n                    else\n                    {\n                        // A listener that ended no longer holds its shortcut. Nothing here ties the listener's descendants to this program\n                        // (the browser window must survive a restart): helpers end when their own input closes.\n                        ForgetReadyStatus();\n                        try\n                        {\n                            var psi = new ProcessStartInfo(settings.Node);\n                            psi.Arguments = \"\\\"\" + settings.Cli + \"\\\" hud listen\";\n                            psi.UseShellExecute = false;\n                            psi.CreateNoWindow = true;\n                            psi.WindowStyle = ProcessWindowStyle.Hidden;\n                            psi.RedirectStandardOutput = true;\n                            psi.RedirectStandardError = true;\n                            // The listener watches this open pipe: if this program ends for any reason, the pipe closes and the listener stops.\n                            psi.RedirectStandardInput = true;\n                            psi.EnvironmentVariables[\"RH_HUD_OWNER_PIPE\"] = \"1\";\n                            using (Process p = Process.Start(psi))\n                            {\n                                p.OutputDataReceived += delegate(object s, DataReceivedEventArgs e) { if (e.Data != null) Log(e.Data); };\n                                p.ErrorDataReceived += delegate(object s, DataReceivedEventArgs e) { if (e.Data != null) Log(\"error: \" + e.Data); };\n                                p.BeginOutputReadLine();\n                                p.BeginErrorReadLine();\n                                p.WaitForExit();\n                                Log(\"listener ended with code \" + p.ExitCode);\n                            }\n                        }\n                        catch (Exception ex)\n                        {\n                            Log(\"listener could not start: \" + ex.Message);\n                        }\n                        ForgetReadyStatus();\n                    }\n                    // a listener that ran for a while was healthy: start again quickly; one that dies at once waits longer\n                    wait = (DateTime.UtcNow - started).TotalSeconds > 60 ? 1000 : Math.Min(wait * 2, 30000);\n                    Thread.Sleep(wait);\n                }\n            }\n        }\n    }\n\n    static class Program\n    {\n        [STAThread]\n        static int Main(string[] argv)\n        {\n            HudArgs args = HudArgs.Parse(argv);\n            if (args.Mode == \"supervise\") return Supervisor.Run(args);\n            try\n            {\n                Native.SetProcessDPIAware();\n            }\n            catch (Exception)\n            {\n                // an older Windows: the window is simply scaled by the system\n            }\n            Application.EnableVisualStyles();\n            Application.SetCompatibleTextRenderingDefault(false);\n            Dpi.Init();\n            if (args.Mode == \"listen\")\n            {\n                var window = new HotkeyWindow();\n                if (!window.Register())\n                {\n                    Wire.Send(Messages.HotkeyFailed());\n                    return 3;\n                }\n                Wire.Send(Messages.HotkeyReady(window.Keys));\n                // The daemon keeps this program's input open: when that ends, the daemon is gone and so is the need for the hotkey.\n                var watch = new Thread(delegate()\n                {\n                    try\n                    {\n                        StreamReader reader = Wire.Input();\n                        while (reader.ReadLine() != null)\n                        {\n                        }\n                    }\n                    catch (Exception)\n                    {\n                        // treated as the end of the input\n                    }\n                    Environment.Exit(0);\n                });\n                watch.IsBackground = true;\n                watch.Start();\n                Application.Run();\n                return 0;\n            }\n            Application.Run(new PromptForm(args));\n            return 0;\n        }\n    }\n}\n"};
